    const dl=m.querySelector("#lbDl"); dl.innerHTML=`<button type="button" class="btn primary" data-lbdlall>Download print files (.zip)</button>`+parts.map((p,i)=>`<button type="button" class="btn" data-lbdl="${i}">${esc(p.label||p.name.replace(/^.*-/,"").replace(/\.\w+$/,""))} only</button>`).join("");
