  for(let i=0;i<n;i++){ if(dv.getUint32(p,true)!==0x02014b50) break; const method=dv.getUint16(p+10,true), csize=dv.getUint32(p+20,true), nlen=dv.getUint16(p+28,true), elen=dv.getUint16(p+30,true), clen=dv.getUint16(p+32,true), loc=dv.getUint32(p+42,true); const name=td.decode(u8.subarray(p+46,p+46+nlen)); p+=46+nlen+elen+clen;
    const lnlen=dv.getUint16(loc+26,true), lelen=dv.getUint16(loc+28,true); const data=u8.subarray(loc+30+lnlen+lelen, loc+30+lnlen+lelen+csize);
    if(method===0) out[name]=data; else if(method===8){ const ds=new DecompressionStream("deflate-raw"); const w=ds.writable.getWriter(); w.write(data); w.close(); out[name]=new Uint8Array(await new Response(ds.readable).arrayBuffer()); } }
