function qpBBox(parts){ const mn=[1e9,1e9,1e9], mx=[-1e9,-1e9,-1e9]; for(const p of parts) for(let i=0;i<p.tri.length;i+=3) for(let k=0;k<3;k++){ const v=p.tri[i+k]; if(v<mn[k]) mn[k]=v; if(v>mx[k]) mx[k]=v; } return {mn,mx,size:mx.map((v,i)=>v-mn[i])}; }
