      /* normal in world for shading */ const ux=T[i+3]-T[i],uy=T[i+4]-T[i+1],uz=T[i+5]-T[i+2],vx=T[i+6]-T[i],vy=T[i+7]-T[i+1],vz=T[i+8]-T[i+2]; let nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx; const nl=Math.hypot(nx,ny,nz)||1; nx/=nl; ny/=nl; nz/=nl; const nx1=nx*cy-ny*sy, ny1=nx*sy+ny*cy; const nz2=ny1*st+nz*ct, ny2=ny1*ct-nz*st; let lam=Math.abs(nx1*L[0]+ny2*L[1]+nz2*L[2]); const sh=0.35+0.65*lam; const r=Math.round(col[0]*sh), gg=Math.round(col[1]*sh), bl=Math.round(col[2]*sh);
      /* raster */ const minx=Math.max(0,Math.floor(Math.min(a[0],b[0],d[0]))), maxx=Math.min(W-1,Math.ceil(Math.max(a[0],b[0],d[0]))), miny=Math.max(0,Math.floor(Math.min(a[1],b[1],d[1]))), maxy=Math.min(H-1,Math.ceil(Math.max(a[1],b[1],d[1]))); if(minx>maxx||miny>maxy) continue;
