function qpBulkBar(biz,lib){ const n=[...QPB.sel].filter(id=>lib.some(d=>d.id===id)).length; const brand=S.designFilter&&S.designFilter!=="all"?(BRANDS[S.designFilter]||S.designFilter):"all brands";
  return `<div class="qpbulk"><b>Pick & post</b><span class="small muted">tick shirts below, or</span><button type="button" class="btn" data-qpall="1">Select all shown (${lib.length} · ${esc(brand)})</button><button type="button" class="btn" data-qpnone="1" ${n?"":"disabled"}>Clear</button>
    ${biz==="c3d"?`<span class="pill">Etsy · Charleston3DWorks (3D shop) · $0.20 each</span>`:`<select data-qpbchan><option value="both" ${QPB.chan==="both"?"selected":""}>Shopify + Etsy (Elevated Designs shop)</option><option value="shopify" ${QPB.chan==="shopify"?"selected":""}>Shopify only (no listing fee)</option><option value="etsy" ${QPB.chan==="etsy"?"selected":""}>Etsy only · $0.20 each</option></select>`}
    <button type="button" class="btn primary" data-qpbulk="${biz}" ${n&&!QPB.busy?"":"disabled"}>${QPB.busy?"Sending…":`Post ${n} ${biz==="c3d"?"to Etsy":"now"}`}</button>${QPB.msg?`<span class="small muted">${esc(QPB.msg)}</span>`:""}</div>`; }
function bindQuickBulk(){ document.querySelectorAll("[data-dsel]").forEach(c=>c.onchange=()=>{ if(c.checked) QPB.sel.add(c.dataset.dsel); else QPB.sel.delete(c.dataset.dsel); render(); });
  const all=document.querySelector("[data-qpall]"); if(all) all.onclick=()=>{ const biz=S.biz==="c3d"?"c3d":"ed", f=S.designFilter||"all"; S.designs.filter(d=>designBiz(d)===biz&&(f==="all"||d.brand===f)).forEach(d=>QPB.sel.add(d.id)); render(); };
  const none=document.querySelector("[data-qpnone]"); if(none) none.onclick=()=>{ QPB.sel.clear(); render(); };
  const ch=document.querySelector("[data-qpbchan]"); if(ch) ch.onchange=()=>{ QPB.chan=ch.value; };
  const go=document.querySelector("[data-qpbulk]"); if(go) go.onclick=()=>qpBulk(go.dataset.qpbulk); }
async function qpBulk(biz){ if(QPB.busy) return; if(!qpCan()){ toast("Only Aaron, signed in with his PIN, can post from here."); return; } const ds=S.designs.filter(d=>QPB.sel.has(d.id)&&designBiz(d)===biz); if(!ds.length) return; const chan=biz==="c3d"?"etsy":QPB.chan;
  if(chan!=="shopify"&&!(await hqConfirm(`Posting ${ds.length} listing${ds.length===1?"":"s"} to Etsy (${biz==="c3d"?"Charleston3DWorks":"Elevated Designs"} shop) costs $0.20 each = $${(ds.length*0.2).toFixed(2)}, billed by Etsy to your shop. Each renews every 4 months for another $0.20 only if you turn auto-renew on.\n\nPost them?`,{title:"Post to Etsy",ok:`Post ${ds.length} for $${(ds.length*0.2).toFixed(2)}`}))) return;
  QPB.busy=true; QPB.msg="Writing titles and tags…"; render();
  try{ let copies={}; if(sample){ try{ const brand=biz==="c3d"?"Charleston 3D Prints":"Elevated Designs"; const list=ds.slice(0,40).map(d=>({id:d.id,title:d.title||"",brand:BRANDS[d.brand]||d.brand||"",notes:String(d.description||d.prompt||d.concept||"").slice(0,200)}));
      const j=await sample.json(`You write Etsy/Shopify listings for ${brand} (${biz==="c3d"?"3D-printed goods":"graphic t-shirts"}, Charleston SC). For each design below write: title (under 120 chars, front-loaded, no all caps, no brand/character names we don't own), 13 lowercase Etsy tags under 20 chars each, a 120-180 word description (what it is, who it's for, made in Charleston SC, gift angle, care line), one alt text line. Designs: ${JSON.stringify(list)}. Reply with JSON only: {"<id>":{"title":"","tags":[],"description":"","altText":""},...}`,{modelTier:"quick"}); if(j&&typeof j==="object") copies=j; }catch{ QPB.msg="Carla will write the words."; } }
    const now=new Date().toISOString(); const brandKey=biz==="c3d"?"charleston-3d-prints":"elevated-designs"; const ids=[];
    for(const d of ds){ const c=copies[d.id]||{}; const u=assetSrc(d.imageId,d.imageUrl); const photoIds=[d.mockupId,d.imageId].filter(x=>/^[0-9a-f]{32}$/.test(String(x||"")));
      const ref=await db.collection("listings").add({quick:true, bulk:true, biz, brand:d.brand||brandKey, designId:d.id, channel:chan, etsyShop:chan==="shopify"?null:(biz==="c3d"?"c3d":"ed"), feeOk:chan!=="shopify"?{by:"aaron",at:now,perListing:0.2}:null, status:"new", at:now, by:"aaron", approval:"Aaron approved posting this live from Pick & post on "+now.slice(0,10), title:c.title||d.title||"Untitled", description:c.description||"", tags:Array.isArray(c.tags)?c.tags.slice(0,13):[], altText:c.altText||"", photos:u?[u]:[], photoIds, note:`PICK & POST from the Designs page (design designs/${d.id}, brand ${d.brand||brandKey}). Post it live now on ${chan==="both"?"Shopify and Etsy":chan}. ${chan!=="shopify"?`Etsy: Aaron OK'd the $0.20 fee. Post through the Etsy bridge (one-click poster) to the ${biz==="c3d"?"Charleston3DWorks 3D shop":"Elevated Designs shirt shop"}; if the Etsy connection isn't set up yet, set etsyStatus "waiting for Etsy connection" and build the Export pack so nothing is lost. `:""}First photo must be a straight-on view showing the whole design. If the design has no mockup yet, make the mockups first, then post.`}); ids.push(ref.id); }
    const tid=typeof tidOf==="function"?tidOf("carla"):null; let fired=false; if(tid) fired=await fire(tid,`PICK & POST from Aaron: ${ids.length} ${BIZ_NAME[biz]} listing${ids.length===1?"":"s"} (${ids.map(i=>"listings/"+i).join(", ")}) are approved to go live now on ${chan==="both"?"Shopify and Etsy":chan}${chan!=="shopify"?" (Aaron OK'd the $0.20/listing Etsy fee)":""}. Each has a title, tags and description; make mockups where missing, post them, then tell Aaron the links.`);
    QPB.sel.clear(); QPB.msg=`${ids.length} sent. ${fired?"Carla is posting them now.":"Carla posts them on her next run."}`; toast(QPB.msg); }
  catch(e){ QPB.msg="Stopped: "+(e&&e.message?e.message:"something went wrong"); }
  QPB.busy=false; render(); }
/* ---- STORE CONTROL: what is live on Shopify / Etsy, add or take off from here (Carla syncs and executes) ---- */
const STORE={busy:new Set(), q:"", sel:new Set()};
const STORE_FEES={shopify:"Shopify: no per-item fee · 2.9% + 30¢ per sale on the plan",etsy:"Etsy: $0.20 per listing when it goes live (renews every 4 months) · 6.5% + 3% + 25¢ per sale"};
function storeItems(platform,biz){ const d=(S.shop||{})[platform+"-"+biz]; return d&&Array.isArray(d.items)?d.items:[]; }
function storeCard(biz){ const bn=BIZ_NAME[biz]; const plats=[["shopify","Shopify"],["etsy","Etsy"]]; const pend=(S.storeops||[]).filter(o=>o.biz===biz&&o.status!=="done");
  const row=(p,it)=>{ const live=/^(active|live|published)$/i.test(it.status||""); const k=p+":"+it.id; const pendOp=pend.find(o=>o.platform===p&&String(o.productId)===String(it.id)); const img=safeImg(it.image||""); 
    return `<div class="strow ${live?"live":"off"}">${qpCan()?`<input type="checkbox" data-stsel="${esc(k)}" ${STORE.sel.has(k)?"checked":""} aria-label="Select">`:""}<img src="${esc(img||"")}" alt="" ${img?"":"hidden"}><div class="st-t"><b>${esc(String(it.title||"Untitled").slice(0,70))}</b><span class="small muted">${it.price?"$"+esc(String(it.price)):""}${it.brand?" · "+esc(it.brand):""}${it.url?` · <a href="${esc(it.url)}" target="_blank" rel="noopener">open</a>`:""}</span></div>
      <span class="pill ${live?"ok":""}">${esc(pendOp?(pendOp.op==="publish"?"going live…":"coming off…"):(it.status||"?"))}</span>
      ${qpCan()?`<button type="button" class="btn ${live?"":"primary"}" data-storeop="${live?"unpublish":"publish"}" data-stp="${p}" data-stid="${esc(String(it.id))}" data-stbiz="${biz}" ${STORE.busy.has(k)||pendOp?"disabled":""}>${live?"Take off":"Put on"}</button>`:""}</div>`; };
  const q=STORE.q.toLowerCase();
  return `<section class="card" id="store-${biz}"><div class="card-head"><h2 class="big">What's for sale · ${esc(bn)}</h2><span class="eyebrow">the one place between you and the shops</span></div>
    <p class="small muted" style="margin-top:0">Everything live on Shopify and Etsy, as Carla last saw it. <b>Take off</b> hides it from the shop (nothing is deleted); <b>Put on</b> makes it live again. Carla does it within minutes and refreshes this list every run.</p>
    <div class="row" style="gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px"><input type="search" data-stq placeholder="Find a product…" value="${esc(STORE.q)}" style="flex:1;min-width:180px"><select data-stonly aria-label="Show"><option value="all" ${STORE.only==="all"||!STORE.only?"selected":""}>All</option><option value="live" ${STORE.only==="live"?"selected":""}>Live only</option><option value="off" ${STORE.only==="off"?"selected":""}>Off / draft only</option></select>${qpCan()?`<button type="button" class="btn" data-stsync="${biz}">Refresh from the shops</button>`:""}</div>
    ${qpCan()?`<div class="row stbulk" style="gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px"><b>${STORE.sel.size} selected</b><button type="button" class="btn primary" data-stbulk="publish" data-stbiz="${biz}" ${STORE.sel.size?"":"disabled"}>Put selected on sale</button><button type="button" class="btn" data-stbulk="unpublish" data-stbiz="${biz}" ${STORE.sel.size?"":"disabled"}>Take selected off</button><button type="button" class="btn ghost" data-stselall="${biz}">Select all shown</button><button type="button" class="btn ghost" data-stselnone="1">Clear</button><span class="small muted" style="flex-basis:100%">Fees: ${esc(STORE_FEES.shopify)} · ${esc(STORE_FEES.etsy)}. One tap sends the whole batch to Carla right now; nothing is ever deleted.</span></div>`:""}
    <div class="stcols">${plats.map(([p,label])=>{ const items=storeItems(p,biz).filter(it=>!q||String(it.title||"").toLowerCase().includes(q)); const d=(S.shop||{})[p+"-"+biz]; const live=items.filter(it=>/^(active|live|published)$/i.test(it.status||"")).length;
      const shown=(STORE.only==="live"?items.filter(it=>/^(active|live|published)$/i.test(it.status||"")):STORE.only==="off"?items.filter(it=>!/^(active|live|published)$/i.test(it.status||"")):items).slice(0,80);
      return `<div class="stcol"><h3>${label} <span class="muted small">· ${live} live${items.length>live?` · ${items.length-live} off`:""}${d&&d.at?" · checked "+esc(typeof fmtAgo==="function"?fmtAgo(d.at):String(d.at).slice(0,16)):""}</span></h3>${items.length?shown.map(it=>row(p,it)).join("")+(shown.length<items.length?`<p class="small muted">Showing ${shown.length} of ${items.length} — search or filter to narrow.</p>`:""):`<p class="muted small">${d?"Nothing listed here yet.":"Carla hasn't synced "+label+" yet. Tap Refresh."}</p>`}</div>`; }).join("")}</div></section>`; }
function bindStore(){ document.querySelectorAll("[data-storeop]").forEach(b=>b.onclick=()=>storeOp(b.dataset.storeop,b.dataset.stp,b.dataset.stid,b.dataset.stbiz));
  document.querySelectorAll("[data-stsel]").forEach(c=>c.onchange=()=>{ if(c.checked) STORE.sel.add(c.dataset.stsel); else STORE.sel.delete(c.dataset.stsel); render(); });
  document.querySelectorAll("[data-stselall]").forEach(b=>b.onclick=()=>{ const biz=b.dataset.stselall, q=STORE.q.toLowerCase(); ["shopify","etsy"].forEach(p=>{ let items=storeItems(p,biz).filter(it=>!q||String(it.title||"").toLowerCase().includes(q)); const L=it=>/^(active|live|published)$/i.test(it.status||""); if(STORE.only==="live") items=items.filter(L); if(STORE.only==="off") items=items.filter(it=>!L(it)); items.slice(0,80).forEach(it=>STORE.sel.add(p+":"+it.id)); }); render(); });
  document.querySelectorAll("[data-stselnone]").forEach(b=>b.onclick=()=>{ STORE.sel.clear(); render(); });
  document.querySelectorAll("[data-stbulk]").forEach(b=>b.onclick=()=>storeBulk(b.dataset.stbulk,b.dataset.stbiz)); const so=document.querySelector("[data-stonly]"); if(so) so.onchange=()=>{ STORE.only=so.value; render(); }; const q=document.querySelector("[data-stq]"); if(q) q.oninput=()=>{ STORE.q=q.value; clearTimeout(STORE.t); STORE.t=setTimeout(render,250); };
  document.querySelectorAll("[data-stsync]").forEach(b=>b.onclick=async()=>{ const tid=typeof tidOf==="function"?tidOf("carla"):null; if(!tid){ toast("Carla's schedule isn't loaded yet."); return; } b.disabled=true; const ok=await fire(tid,`STORE SYNC requested by Aaron from the console: refresh shop/shopify-ed, shop/shopify-c3d, shop/etsy-ed and shop/etsy-c3d now (every product with id, title, status, price, image, url, brand), then stop.`); toast(ok?"Carla is refreshing the list.":"Queued for Carla's next run."); }); }
async function storeOp(op,platform,productId,biz){ if(!qpCan()){ toast("Only Aaron, signed in with his PIN, can change the shops."); return; } const k=platform+":"+productId; if(STORE.busy.has(k)) return; STORE.busy.add(k); render();
  try{ const it=storeItems(platform,biz).find(x=>String(x.id)===String(productId))||{}; const now=new Date().toISOString();
    const ref=await db.collection("storeops").add({op, platform, productId:String(productId), title:it.title||"", biz, by:"aaron", status:"new", at:now, approval:"Aaron tapped "+(op==="publish"?"Put on":"Take off")+" in the console on "+now.slice(0,10)});
    const tid=typeof tidOf==="function"?tidOf("carla"):null; if(tid) await fire(tid,`STORE OP from Aaron: ${op==="publish"?"PUT ON SALE":"TAKE OFF SALE"} "${it.title||productId}" on ${platform} (storeops/${ref.id}, product ${productId}, ${BIZ_NAME[biz]}). Do it now (unpublish = set to draft/inactive, never delete), mark the op done, refresh shop/${platform}-${biz}.`);
    toast(op==="publish"?"Carla is putting it on.":"Carla is taking it off."); }
  catch{ toast("Couldn't send that. Try again."); }
  STORE.busy.delete(k); render(); }

async function storeBulk(op,biz){ if(!qpCan()){ toast("Only Aaron, signed in with his PIN, can change the shops."); return; } const keys=[...STORE.sel]; if(!keys.length) return; if(STORE.bulkBusy) return; STORE.bulkBusy=true; render();
  try{ const now=new Date().toISOString(); const lines=[]; const refs=[];
    for(const k of keys){ const [platform,...rest]=k.split(":"); const productId=rest.join(":"); const it=storeItems(platform,biz).find(x=>String(x.id)===String(productId)); if(!it) continue; const live=/^(active|live|published)$/i.test(it.status||""); if((op==="publish")===live) continue;
      const ref=await db.collection("storeops").add({op, platform, productId:String(productId), title:it.title||"", biz, by:"aaron", status:"new", at:now, bulk:true, approval:"Aaron tapped "+(op==="publish"?"Put selected on sale":"Take selected off")+" in the console on "+now.slice(0,10)}); refs.push(ref.id); lines.push(`${platform}: "${it.title||productId}" (product ${productId}, storeops/${ref.id})`); }
    if(!lines.length){ toast(op==="publish"?"Everything selected is already live.":"Everything selected is already off."); STORE.sel.clear(); STORE.bulkBusy=false; render(); return; }
    const tid=typeof tidOf==="function"?tidOf("carla"):null; let fired=false; if(tid) fired=await fire(tid,`STORE OPS (batch) from Aaron: ${op==="publish"?"PUT ON SALE":"TAKE OFF SALE"} these ${lines.length} ${BIZ_NAME[biz]} products now (unpublish = draft/inactive, never delete; Etsy publish = make the listing active, Aaron knows about the $0.20 listing fee): ${lines.join("; ")}. Mark each storeops doc done, then refresh shop/shopify-${biz} and shop/etsy-${biz}.`);
    STORE.sel.clear(); toast(`${lines.length} sent. ${fired?"Carla is on it now.":"Carla does it on her next run."}`); }
  catch{ toast("Couldn't send the batch. Try again."); }
  STORE.bulkBusy=false; render(); }

/* ================= CODE: your GitHub repos inside the console — browse, edit, save (Sam commits), export ================= */
const CODE={repo:null, path:null, text:"", orig:"", open:new Set(), q:"", msg:"", busy:false, dirty:false};
function codeRepos(){ return (S.repos||[]).slice().sort((a,b)=>String(a.name).localeCompare(String(b.name))); }
function codeRepo(){ const rs=codeRepos(); if(!rs.length) return null; let r=rs.find(x=>x.id===CODE.repo); if(!r){ r=rs[0]; CODE.repo=r.id; } return r; }
function codeFileId(repo,path){ return repo+"__"+String(path).replace(/[^a-zA-Z0-9._-]+/g,"-"); }
function codeFile(repo,path){ return (S.repofiles||{})[codeFileId(repo,path)]||null; }
function vCode(){ const r=codeRepo(); const rs=codeRepos(); const pend=(S.repochanges||[]).filter(c=>c.status!=="done").length;
  if(!r) return reengPanel()+`<section class="card"><div class="card-head"><h2 class="big">Code</h2><span class="eyebrow">your GitHub repos, right here</span></div><p class="muted">Sam hasn't mirrored your repos yet. ${qpCan()?`<button type="button" class="btn primary" data-codesync>Ask Sam to pull them in now</button>`:"Aaron can ask Sam to pull them in."}</p></section>`;
  const tree=Array.isArray(r.tree)?r.tree:[]; const q=CODE.q.toLowerCase(); const shown=q?tree.filter(f=>f.path.toLowerCase().includes(q)):tree;
  const f=CODE.path?codeFile(r.id,CODE.path):null; const meta=tree.find(t=>t.path===CODE.path);
  return reengPanel()+`<section class="card codepage"><div class="card-head"><h2 class="big">Code</h2><span class="eyebrow">${esc(r.name)} · ${esc(r.branch||"main")} · ${tree.length} files${r.syncedAt?" · pulled "+esc(typeof fmtAgo==="function"?fmtAgo(r.syncedAt):String(r.syncedAt).slice(0,16)):""}${pend?` · ${pend} change${pend===1?"":"s"} waiting for Sam`:""}</span></div>
    <div class="row" style="gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px">
      <select data-coderepo>${rs.map(x=>`<option value="${esc(x.id)}" ${x.id===r.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select>
      <input type="search" data-codeq placeholder="Find a file…" value="${esc(CODE.q)}" style="flex:1;min-width:160px">
      ${r.url?`<a class="btn" href="${esc(r.url)}" target="_blank" rel="noopener">Open on GitHub</a>`:""}
      ${qpCan()?`<button type="button" class="btn" data-codesync>Pull latest</button><button type="button" class="btn" data-codenew>New file</button>`:""}
      <button type="button" class="btn" data-codezip>Export repo (.zip)</button></div>
    <div class="codewrap">
      <div class="codetree">${codeTree(shown,r)}</div>
      <div class="codeview">${CODE.path?`<div class="codehead"><b>${esc(CODE.path)}</b><span class="small muted">${meta?esc(fmtBytes(meta.size||0)):""}${f&&f.bin?" · binary":""}${f&&f.truncated?" · too big to edit here":""}</span>
          <span class="codeacts">${CODE.path&&f&&!f.bin?`<button type="button" class="btn" data-codedl>Export file</button>`:""}${qpCan()&&f&&!f.bin&&!f.truncated?`<button type="button" class="btn primary" data-codesave ${CODE.dirty&&!CODE.busy?"":"disabled"}>${CODE.busy?"Saving…":"Save to GitHub"}</button>`:""}</span></div>
          ${f?(f.bin?`<p class="muted small" style="padding:12px">Binary file. ${r.url?`<a href="${esc(r.url)}/blob/${esc(r.branch||"main")}/${esc(CODE.path)}" target="_blank" rel="noopener">Open it on GitHub</a>`:""}</p>`:`<textarea class="codeed" data-codeed spellcheck="false" ${f.truncated?"readonly":""}>${esc(CODE.text)}</textarea>`):`<p class="muted small" style="padding:12px">Sam hasn't copied this file yet. Tap "Pull latest".</p>`}
          ${qpCan()?`<div class="codeask"><input type="text" data-codeask placeholder="Tell Sam what to change in this file (or the whole repo)…" maxlength="500"><button type="button" class="btn" data-codeaskgo>Send to Sam</button></div>`:""}
          ${CODE.msg?`<p class="small muted" style="padding:0 12px 8px">${esc(CODE.msg)}</p>`:""}`:`<p class="muted" style="padding:14px">Pick a file on the left. Edit it here and Save — Sam commits and pushes it within minutes. Export gives you the file or the whole repo as a zip.</p>`}</div>
    </div></section>`; }
function fmtBytes(n){ return n<1024?n+" B":n<1048576?(n/1024).toFixed(1)+" KB":(n/1048576).toFixed(1)+" MB"; }
function codeTree(files,r){ const root={d:{},f:[]}; for(const f of files){ const parts=f.path.split("/"); let n=root; for(let i=0;i<parts.length-1;i++){ n=n.d[parts[i]]=n.d[parts[i]]||{d:{},f:[]}; } n.f.push({name:parts[parts.length-1],...f}); }
  const draw=(n,prefix,depth)=>{ const dirs=Object.keys(n.d).sort(); const fs=n.f.slice().sort((a,b)=>a.name.localeCompare(b.name)); return dirs.map(d=>{ const p=prefix+d; const open=CODE.open.has(p)||!!CODE.q; return `<div class="cdir"><button type="button" class="cdirb" data-codedir="${esc(p)}" style="padding-left:${8+depth*12}px">${open?"▾":"▸"} ${esc(d)}/</button>${open?draw(n.d[d],p+"/",depth+1):""}</div>`; }).join("")+fs.map(f=>`<button type="button" class="cfile ${f.path===CODE.path?"on":""}" data-codefile="${esc(f.path)}" style="padding-left:${8+depth*12}px">${esc(f.name)}</button>`).join(""); };
  return draw(root,"",0)||`<p class="muted small" style="padding:8px">No files${CODE.q?" match":""}.</p>`; }
function bindCode(){ bindReeng(); if(S.tab!=="code") return; const r=codeRepo();
  const sel=document.querySelector("[data-coderepo]"); if(sel) sel.onchange=async()=>{ if(!(await codeLeaveOk())) { sel.value=CODE.repo; return; } CODE.repo=sel.value; CODE.path=null; CODE.dirty=false; CODE.msg=""; render(); };
  const q=document.querySelector("[data-codeq]"); if(q) q.oninput=()=>{ CODE.q=q.value; clearTimeout(CODE.t); CODE.t=setTimeout(render,200); };
  document.querySelectorAll("[data-codedir]").forEach(b=>b.onclick=()=>{ const p=b.dataset.codedir; if(CODE.open.has(p)) CODE.open.delete(p); else CODE.open.add(p); render(); });
  document.querySelectorAll("[data-codefile]").forEach(b=>b.onclick=()=>codeOpen(b.dataset.codefile));
  const ed=document.querySelector("[data-codeed]"); if(ed){ ed.oninput=()=>{ CODE.text=ed.value; const d=CODE.text!==CODE.orig; if(d!==CODE.dirty){ CODE.dirty=d; const sb=document.querySelector("[data-codesave]"); if(sb) sb.disabled=!d; } }; ed.onkeydown=e=>{ if((e.ctrlKey||e.metaKey)&&e.key==="s"){ e.preventDefault(); codeSave(); } if(e.key==="Tab"){ e.preventDefault(); const s=ed.selectionStart; ed.value=ed.value.slice(0,s)+"  "+ed.value.slice(ed.selectionEnd); ed.selectionStart=ed.selectionEnd=s+2; ed.oninput(); } }; }
  const sv=document.querySelector("[data-codesave]"); if(sv) sv.onclick=codeSave;
  const dl=document.querySelector("[data-codedl]"); if(dl) dl.onclick=()=>codeDownload(new Blob([CODE.text],{type:"text/plain"}),CODE.path.split("/").pop());
  const zip=document.querySelector("[data-codezip]"); if(zip) zip.onclick=codeZip;
  document.querySelectorAll("[data-codesync]").forEach(b=>b.onclick=async()=>{ const tid=typeof tidOf==="function"?tidOf("sam"):null; if(!tid){ toast("Sam's schedule isn't loaded yet."); return; } b.disabled=true; const ok=await fire(tid,`REPO SYNC requested by Aaron from the console's Code page: mirror every GitHub repo now (repos/<slug> + repofiles), then stop.`); toast(ok?"Sam is pulling the repos now.":"Queued for Sam's next run."); });
  const nf=document.querySelector("[data-codenew]"); if(nf) nf.onclick=async()=>{ if(!(await codeLeaveOk())) return; const p=await hqPrompt("New file path (e.g. src/notes.md)","",{title:"New file",ok:"Create"}); if(!p) return; const path=p.trim().replace(/^\/+/,""); if(!path) return; S.repofiles=S.repofiles||{}; S.repofiles[codeFileId(r.id,path)]={path,text:"",local:true}; if(!r.tree.some(t=>t.path===path)) r.tree.push({path,size:0}); CODE.path=path; CODE.text=""; CODE.orig=null; CODE.dirty=true; render(); };
  const ask=document.querySelector("[data-codeaskgo]"); if(ask) ask.onclick=async()=>{ const i=document.querySelector("[data-codeask]"); const t=(i.value||"").trim(); if(!t) return; ask.disabled=true; try{ const now=new Date().toISOString(); const ref=await db.collection("requests").add({for:"sam", by:"aaron", what:`CODE (${r.name}${CODE.path?" · "+CODE.path:""}): ${t}`, repo:r.id, path:CODE.path||"", status:"open", at:now}); const tid=typeof tidOf==="function"?tidOf("sam"):null; if(tid) await fire(tid,`CODE REQUEST from Aaron (requests/${ref.id}) on repo ${r.name}${CODE.path?" file "+CODE.path:""}: ${t}. Make the change on a branch or main as the request says (default main), push, then re-mirror the repo.`); i.value=""; CODE.msg="Sent to Sam. He commits it and the file refreshes here."; toast("Sent to Sam."); }catch{ toast("Couldn't send that."); } ask.disabled=false; render(); }; }
async function codeLeaveOk(){ return !CODE.dirty||await hqConfirm("You have unsaved changes. Leave anyway?",{ok:"Leave",danger:true}); }
async function codeFetch(repo,path){ const id=codeFileId(repo,path); S.repofiles=S.repofiles||{}; if(S.repofiles[id]) return S.repofiles[id]; if(!db) return null; try{ const d=await db.doc("repofiles/"+id).get(); if(d&&d.exists){ S.repofiles[id]=d.data(); return S.repofiles[id]; } }catch{} return null; }
async function codeOpen(path){ if(path===CODE.path) return; if(!(await codeLeaveOk())) return; const r=codeRepo(); CODE.path=path; CODE.text=""; CODE.orig=""; CODE.dirty=false; CODE.msg="Loading…"; render(); const f=await codeFetch(r.id,path); if(CODE.path!==path) return; CODE.text=f&&!f.bin?String(f.text||""):""; CODE.orig=CODE.text; CODE.msg=""; render(); }
async function codeSave(){ if(!CODE.dirty||CODE.busy||!qpCan()) return; const r=codeRepo(); if(!r||!CODE.path) return; const msg=((await hqPrompt("Commit message","Edit "+CODE.path+" from the console",{title:"Save to GitHub",ok:"Save"}))||"").trim(); if(!msg) return; CODE.busy=true; render();
  try{ const now=new Date().toISOString(); const ref=await db.collection("repochanges").add({repo:r.id, repoName:r.name, branch:r.branch||"main", path:CODE.path, text:CODE.text, message:msg, by:"aaron", status:"new", at:now});
    S.repofiles=S.repofiles||{}; const id=codeFileId(r.id,CODE.path); S.repofiles[id]={...(S.repofiles[id]||{}),path:CODE.path,text:CODE.text,pending:true}; CODE.orig=CODE.text; CODE.dirty=false;
    const tid=typeof tidOf==="function"?tidOf("sam"):null; let fired=false; if(tid) fired=await fire(tid,`REPO CHANGE from Aaron (repochanges/${ref.id}): write the file ${CODE.path} in ${r.name} (${r.branch||"main"}) with the text in the doc, commit "${msg}", push, mark the change done, re-mirror that repo.`);
    CODE.msg=fired?"Saved. Sam is committing and pushing it now.":"Saved. Sam commits it on his next run."; toast("Saved — Sam is pushing it."); }
  catch{ CODE.msg="Couldn't save. Try again."; }
  CODE.busy=false; render(); }
async function codeDownload(blob,name){ return dlBlob(name,blob); }
async function codeZip(){ const r=codeRepo(); if(!r||typeof mkZip!=="function") return; const files=[]; let skipped=0; toast("Gathering files…"); for(const t of (r.tree||[])){ const f=await codeFetch(r.id,t.path); if(f&&!f.bin&&!f.truncated) files.push({name:t.path,data:String(f.text||"")}); else skipped++; } if(!files.length){ toast("Nothing mirrored yet."); return; }
  const blob=mkZip(files); await codeDownload(new Blob([blob],{type:"application/zip"}),(r.name||"repo").replace(/[^\w.-]+/g,"-")+".zip"); if(skipped) toast(`${skipped} binary or oversized file${skipped===1?"":"s"} left out — they're on GitHub.`); }

/* ================= RE-ENGINEER: point it at a repo, one of your apps, or any link; say what you want; Sam mirrors it, applies the change on a copy, and the diff comes back here ================= */
const REENG={src:"repo",busy:false,msg:""};
function reengPanel(){ const rs=codeRepos(); const apps=(S.apps||[]).filter(a=>a.liveUrl||a.prototypeUrl); const own=qpCan(); const pend=(S.repochanges||[]).filter(c=>/^RE-ENGINEER/i.test(c.what||c.note||"")&&c.status!=="done");
  return `<section class="card reeng"><div class="card-head"><h2 class="big">Re-engineer</h2><span class="eyebrow">repo · app · link → describe the change → review the diff → export</span></div>
    <div class="reeng-src chips" role="group" aria-label="Source">${[["repo","A GitHub repo"],["app","One of my apps"],["link","A link"]].map(([k,l])=>`<button type="button" class="chip" data-reengsrc="${k}" aria-pressed="${REENG.src===k?"true":"false"}">${l}</button>`).join("")}</div>
    <div class="reeng-row">${REENG.src==="repo"?`<select data-reengrepo>${rs.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join("")}<option value="__new">Paste a public repo link…</option></select><input type="url" data-reengurl placeholder="https://github.com/owner/repo (public, licence permitting)" style="flex:1;min-width:200px">`
      :REENG.src==="app"?`<select data-reengapp>${apps.map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc((a.liveUrl||a.prototypeUrl||"").replace(/^https?:\/\//,"").slice(0,40))}</option>`).join("")||`<option value="">No apps with a link yet</option>`}</select>`
      :`<input type="url" data-reengurl placeholder="https://… any page or web app" style="flex:1;min-width:240px">`}</div>
    <textarea data-reengwhat rows="3" placeholder="What do you want? e.g. turn this into a phone-first PWA with our dark theme · pull the shirt mockup code out into its own tool · rewrite in plain JS, no framework, keep every feature" maxlength="1200"></textarea>
    <div class="row" style="gap:8px;flex-wrap:wrap;align-items:center;margin-top:8px">${own?`<button type="button" class="btn primary" data-reenggo ${REENG.busy?"disabled":""}>${REENG.busy?"Sending…":"Re-engineer → Sam builds a copy"}</button>`:`<span class="small muted">Aaron starts re-engineering jobs.</span>`}<span class="small muted">Sam checks the licence first. For a link he saves the page and the CSS/JS it can see — server code never comes through, and he says what's missing.</span></div>
    ${REENG.msg?`<p class="small" style="margin:8px 0 0">${esc(REENG.msg)}</p>`:""}
    ${pend.length?`<div class="small muted" style="margin-top:8px">${pend.length} re-engineering job${pend.length===1?"":"s"} with Sam: ${pend.map(c=>esc(String(c.what||"").replace(/^RE-ENGINEER:\s*/i,"").slice(0,70))).join(" · ")}</div>`:""}
  </section>`; }
function bindReeng(){ document.querySelectorAll("[data-reengsrc]").forEach(b=>b.onclick=()=>{ REENG.src=b.dataset.reengsrc; render(); });
  const go=document.querySelector("[data-reenggo]"); if(go) go.onclick=reengGo; }
async function reengGo(){ if(!db||!qpCan()||REENG.busy) return; const what=(document.querySelector("[data-reengwhat]")||{}).value||""; if(what.trim().length<8){ toast("Say what you want changed."); return; }
  let src="", slug="";
  if(REENG.src==="repo"){ const sel=document.querySelector("[data-reengrepo]"); const url=(document.querySelector("[data-reengurl]")||{}).value||""; if(sel&&sel.value&&sel.value!=="__new"){ const r=codeRepos().find(x=>x.id===sel.value); src=`repo ${r?r.name:sel.value} (repos/${sel.value}${r&&r.url?", "+r.url:""})`; slug=sel.value; } else { if(!/^https?:\/\/github\.com\//.test(url)){ toast("Paste a github.com link."); return; } src=`public repo ${url}`; slug=url.replace(/^https?:\/\/github\.com\//,"").replace(/[^a-z0-9]+/gi,"-").toLowerCase(); } }
  else if(REENG.src==="app"){ const sel=document.querySelector("[data-reengapp]"); const a=(S.apps||[]).find(x=>x.id===(sel&&sel.value)); if(!a){ toast("Pick an app."); return; } src=`my app "${a.name}" (apps/${a.id}, ${a.liveUrl||a.prototypeUrl}${a.netlifySiteId?", Netlify site "+a.netlifySiteId:""})`; slug="app-"+a.id; }
  else { const url=(document.querySelector("[data-reengurl]")||{}).value||""; if(!/^https?:\/\//.test(url)){ toast("Paste a full link."); return; } src=`link ${url}`; slug="link-"+url.replace(/^https?:\/\//,"").replace(/[^a-z0-9]+/gi,"-").toLowerCase().slice(0,50); }
  REENG.busy=true; render();
  try{ const now=new Date().toISOString(); const id="reeng-"+Date.now().toString(36);
    await db.doc("repochanges/"+id).set({id,kind:"reengineer",source:src,slug:slug+"-reeng",what:"RE-ENGINEER: "+what.trim(),status:"open",by:"aaron",at:now});
    await db.collection("requests").add({for:"sam",by:"aaron",status:"open",at:now,what:`RE-ENGINEER (repochanges/${id}): source = ${src}. Aaron wants: ${what.trim()}. Steps: 1) check the licence/terms - if it does not allow copying, stop and write that in repochanges/${id}.result and tell Stephanie; 2) mirror the source into repos/${slug}-reeng (for a link: fetch the page and every CSS/JS/image it links that you can read; list what is server-side and could not be fetched; for one of Aaron's apps use the app's own source); 3) apply the change on that copy, keep every working feature unless told otherwise; 4) write all files to repofiles, set repochanges/${id} {status:"done", result: one paragraph, changedFiles:[paths], notes: what could not be done}; 5) tell Stephanie in one line. Never spend money or create accounts.`});
    const tid=typeof tidOf==="function"?tidOf("sam"):null; if(tid) fire(tid,`RE-ENGINEER job from Aaron: repochanges/${id} - do it this run.`);
    REENG.msg="Sent to Sam. The copy shows up in the repo list as "+slug+"-reeng when he's done, with a diff in Changes."; toast("Sam has it."); }
  catch(e){ console.error(e); toast("Couldn't send that."); }
  REENG.busy=false; render(); }

/* ================= AGENT STUDIO: describe an agent → refine → full sellable package (spec, niche, pricing, listing, go-to-market) ================= */
const AG={ideas:[], ideaSrc:{hot:true,ops:true,research:true}, sel:null, brief:"", name:"", busy:"", sugg:[], qs:[], pkg:null, tab:"agent", msg:"", edits:{}};
const AG_SECTIONS=[["agent","The agent"],["skills","Skills & playbooks"],["field","Field research"],["niche","Niche & market"],["pricing","Pricing & money"],["listing","Listing"],["gtm","Go to market"],["quality","Quality bar & risks"]];
const AG_STARTERS=[["Listing Doctor","Every night, read a small Etsy or Shopify shop's listings, find the ones with no sales in 30 days, rewrite title, tags and description from what is ranking now, flag weak first photos, and send the owner a one-line report with before/after. Customers: shops under $5k/month. Never changes prices or deletes anything."],
 ["Lead Responder","Answer new leads for a local service business (HVAC, roofing, detailing) within 60 seconds by text and email, qualify them with 3 questions, book them on the calendar, and hand off anything it can't answer to the owner with a summary. Customers: one-truck operators who miss calls. Never quotes prices it wasn't given."],
 ["Clip Repurposer","Take a creator's new long video, cut the 5 best moments into vertical clips with captions and a hook, write the titles and descriptions, and queue them for approval. Customers: YouTubers with 10k-200k subs and no editor. Never posts without approval."],
 ["Review Replier","Read every new Google, Yelp and Facebook review for a small business each hour, draft a reply in the owner's voice, post 5-star replies automatically and hold anything 3 stars or below for the owner with a suggested fix. Never argues, never offers refunds."],
 ["Inventory Watcher","For a maker who sells on Etsy, Shopify and at markets, watch stock across all of them, warn before a sell-out, suggest reorder quantities from the last 8 weeks of sales, and write a Monday restock list. Never places orders."],
 ["Grant Scout","Every week find grants, vendor events and wholesale buyers a small Charleston business qualifies for, score them by fit and effort, draft the first application paragraph, and put deadlines on a calendar. Never submits anything."]];
function agList(){ return (S.agentproducts||[]).slice().sort((a,b)=>String(b.updatedAt||b.at).localeCompare(String(a.updatedAt||a.at))); }
function agCan(){ return typeof IS_OWNER!=="undefined"&&IS_OWNER; }
function vAgentStudio(){ const list=agList(); const cur=AG.sel?list.find(x=>x.id===AG.sel):null; if(cur&&!AG.pkg&&cur.pkg){ AG.pkg=cur.pkg; AG.brief=cur.brief||""; AG.name=cur.name||""; }
  return `<section class="card agst"><div class="card-head"><h2 class="big">Agent Studio</h2><span class="eyebrow">describe it → refine it → a product you can sell</span></div>
    <p class="small muted" style="margin-top:0">Write what the agent should do and how. I'll suggest what to add, then build the whole package: the agent itself (instructions, tools, schedule, guardrails), the niche it attacks, pricing, a listing, and the launch plan. Everything is editable and saved here.</p>
    <div class="agwrap">
      <aside class="aglist"><button type="button" class="btn ${AG.sel?"":"primary"}" data-agnew>+ New agent</button>
        ${list.map(a=>`<button type="button" class="agitem ${a.id===AG.sel?"on":""}" data-agopen="${esc(a.id)}"><b>${esc(a.name||"Untitled agent")}</b><span class="small muted">${esc(a.pkg&&a.pkg.tagline?String(a.pkg.tagline).slice(0,70):String(a.brief||"").slice(0,70))}</span><span class="pill">${esc(a.stage||"idea")}</span></button>`).join("")}</aside>
      <div class="agmain">
        <label class="lbname">Agent name<input type="text" data-agname maxlength="60" placeholder="e.g. Listing Doctor — fixes dead Etsy listings overnight" value="${esc(AG.name)}"></label>
        <label class="lbname">What should it do, for whom, and how?<textarea data-agbrief rows="6" placeholder="Example: Every night, read a small Etsy shop's listings, find the ones with no sales in 30 days, rewrite the title and tags using what's ranking, redo the first photo, and send the owner a one-line report. Customers: Etsy sellers under $5k/month. It should never change prices.">${esc(AG.brief)}</textarea></label>
        <div class="row" style="gap:8px;flex-wrap:wrap"><button type="button" class="btn" data-agrefine ${AG.busy?"disabled":""}>${AG.busy==="refine"?"Thinking…":"Refine & suggest"}</button><button type="button" class="btn primary" data-agbuild ${AG.busy?"disabled":""}>${AG.busy==="build"?"Building the package…":(AG.pkg?"Rebuild the package":"Build the package")}</button>${AG.pkg?`<button type="button" class="btn" data-agsave ${AG.busy?"disabled":""}>Save</button><button type="button" class="btn" data-agexport>Export (.md)</button>`:""}${AG.msg?`<span class="small muted">${esc(AG.msg)}</span>`:""}</div>
        ${!AG.pkg?`<div class="agsugg agideas"><div class="row" style="gap:8px;flex-wrap:wrap;align-items:center"><b class="small">Idea generator</b>${[["hot","Hot markets right now"],["ops","Turn parts of my operation into products"],["research","From my research & knowledge"]].map(([k,l])=>`<label class="chk small"><input type="checkbox" data-agsrc="${k}" ${AG.ideaSrc[k]?"checked":""}> ${l}</label>`).join("")}<button type="button" class="btn" data-agideas ${AG.busy?"disabled":""}>${AG.busy==="ideas"?"Thinking…":(AG.ideas.length?"More ideas":"Generate ideas")}</button></div>
          ${AG.ideas.length?`<div class="agideagrid">${AG.ideas.map((x,i)=>`<div class="agidea"><b>${esc(x.name)}</b><span class="pill">${esc(x.source||"")} · sellability ${esc(String(x.sellability||"?"))}/5</span><p class="small">${esc(x.oneLiner||"")}</p><p class="small muted">Buyer: ${esc(x.who||"")}<br>Why now: ${esc(x.whyNow||"")}</p><div class="row" style="gap:6px"><button type="button" class="btn primary" data-aguse="${i}">Use this</button><button type="button" class="btn" data-agdrop="${i}">Drop</button></div></div>`).join("")}</div>`:""}</div>`:""}
        ${!AG.brief.trim()&&!AG.pkg?`<div class="agsugg"><p class="small"><b>Start from one of these, then make it yours:</b></p><div class="agchips">${AG_STARTERS.map((x,i)=>`<button type="button" class="chip" data-agstart="${i}">${esc(x[0])}</button>`).join("")}</div></div>`:""}
        ${AG.qs.length||AG.sugg.length?`<div class="agsugg">${AG.qs.length?`<p class="small"><b>Answer these in the brief and it gets sharper:</b></p><ul class="small">${AG.qs.map(q=>`<li>${esc(q)}</li>`).join("")}</ul>`:""}${AG.sugg.length?`<p class="small"><b>Tap to add:</b></p><div class="agchips">${AG.sugg.map((s,i)=>`<button type="button" class="chip" data-agadd="${i}">+ ${esc(s)}</button>`).join("")}</div>`:""}</div>`:""}
        ${AG.pkg?agPackage():""}
      </div></div></section>`; }
function agPackage(){ const p=AG.pkg; const t=AG.tab; const sec=(k)=>{ const v=AG.edits[k]!==undefined?AG.edits[k]:agText(p,k); return `<textarea class="agsec" data-agsec="${k}" rows="18">${esc(v)}</textarea><div class="row" style="gap:8px;margin-top:6px"><button type="button" class="btn" data-agregen="${k}" ${AG.busy?"disabled":""}>Regenerate this part</button><span class="small muted">Edit freely — your words win.</span></div>`; };
  return `<div class="agpkg"><div class="aghead"><h3>${esc(p.name||AG.name||"Agent")}</h3><p class="muted">${esc(p.tagline||"")}</p>${p.verdict?`<p class="small"><b>Honest read:</b> ${esc(p.verdict)}</p>`:""}</div>
    <div class="chips" style="margin:8px 0">${AG_SECTIONS.map(([k,l])=>`<button type="button" class="chip" aria-pressed="${t===k}" data-agtab="${k}">${l}</button>`).join("")}</div>
    ${sec(t)}
    <div class="agacts"><button type="button" class="btn" data-agship="field" ${agCan()?"":"disabled"}>Research the field (Nora + Sam)</button><button type="button" class="btn primary" data-agship="build" ${agCan()?"":"disabled"}>Build this agent (scheduled task)</button><button type="button" class="btn" data-agship="research" ${agCan()?"":"disabled"}>Nora: validate the niche</button><button type="button" class="btn" data-agship="market" ${agCan()?"":"disabled"}>Tina & Carla: listing + launch</button></div></div>`; }
function agText(p,k){ const j=(v)=>typeof v==="string"?v:JSON.stringify(v,null,2); const a=p.agent||{}, n=p.niche||{}, pr=p.pricing||{}, l=p.listing||{}, g=p.gtm||{};
  if(k==="agent") return `INSTRUCTIONS (the agent's system prompt)\n${a.systemPrompt||""}\n\nTOOLS & ACCESS\n${(a.tools||[]).map(x=>"- "+j(x)).join("\n")}\n\nSCHEDULE\n${a.schedule||""}\n\nINPUTS\n${(a.inputs||[]).map(x=>"- "+j(x)).join("\n")}\n\nOUTPUTS (what the customer gets)\n${(a.outputs||[]).map(x=>"- "+j(x)).join("\n")}\n\nGUARDRAILS\n${(a.guardrails||[]).map(x=>"- "+j(x)).join("\n")}`;
  if(k==="niche") return `WHO BUYS IT\n${n.who||""}\n\nTHE PAIN (and what it costs them today)\n${n.pain||""}\n\nMARKET SIZE & WHY NOW\n${n.size||""}\n${n.whyNow||""}\n\nCOMPETITORS / ALTERNATIVES\n${(n.competitors||[]).map(x=>"- "+j(x)).join("\n")}\n\nOUR EDGE\n${n.edge||""}`;
  if(k==="pricing") return `PRICING TIERS\n${(pr.tiers||[]).map(x=>"- "+j(x)).join("\n")}\n\nMONEY MATH (what it takes to reach the goal)\n${pr.math||""}\n\nOTHER WAYS TO MONETIZE\n${(p.monetization||[]).map(x=>"- "+j(x)).join("\n")}\n\nCOST TO RUN\n${pr.cost||""}`;
  if(k==="listing") return `TITLE\n${l.title||""}\n\nPITCH\n${l.pitch||""}\n\nBULLETS\n${(l.bullets||[]).map(x=>"- "+j(x)).join("\n")}\n\nDEMO / PROOF\n${l.proof||""}\n\nFAQ\n${(l.faq||[]).map(x=>"- "+j(x)).join("\n")}\n\nWHERE TO LIST\n${(l.where||[]).map(x=>"- "+j(x)).join("\n")}`;
  if(k==="gtm") return `FIRST 10 CUSTOMERS\n${(g.firstCustomers||[]).map(x=>"- "+j(x)).join("\n")}\n\nCHANNELS\n${(g.channels||[]).map(x=>"- "+j(x)).join("\n")}\n\n30-DAY LAUNCH PLAN\n${(g.launchPlan||[]).map((x,i)=>(i+1)+". "+j(x)).join("\n")}\n\nCONTENT & PROOF TO MAKE\n${(g.content||[]).map(x=>"- "+j(x)).join("\n")}`;
  if(k==="skills"){ const sk=Array.isArray(p.skills)?p.skills:[]; if(!sk.length) return "(no skills generated yet — tap Rebuild the package)"; return sk.map(x=>`=== SKILL: ${x.name||""} ===\nWHY: ${x.why||""}\n\nRULES OF THE CRAFT\n${(x.rules||[]).map(y=>"- "+j(y)).join("\n")}\n\nSTEPS, EVERY TIME\n${(x.steps||[]).map((y,i)=>(i+1)+". "+j(y)).join("\n")}\n\nVERBIAGE & TEMPLATES\n${(x.verbiage||[]).map(y=>"- "+j(y)).join("\n")}\n\nSELF-CHECKS BEFORE DELIVERING\n${(x.checks||[]).map(y=>"- "+j(y)).join("\n")}\n\nTOP TOOLS\n${(x.tools||[]).map(y=>"- "+j(y)).join("\n")}`).join("\n\n"); }
  if(k==="field"){ const f=p.field||{}; const r=(p.research&&p.research.findings)?"\n\nNORA'S VALIDATION\n"+j(p.research.findings)+"\nSources: "+j(p.research.sources||[]):""; return `TOP AGENTS / PRODUCTS IN THIS SPACE\n${(f.products||[]).map(x=>"- "+j(x)).join("\n")||"(not researched yet — tap \"Research the field\")"}\n\nSKILLS THEY HAVE THAT OURS MUST HAVE\n${(f.skills||[]).map(x=>"- "+j(x)).join("\n")}\n\nOPEN-SOURCE CODE & SKILLS WE CAN BUILD ON (licence allows it)\n${(f.repos||[]).map(x=>"- "+j(x)).join("\n")}\n\nWHAT WE TAKE AND WHAT WE DO BETTER\n${f.plan||""}${r}`; }
  if(k==="quality") return `QUALITY BAR (it ships only when all are true)\n${(p.qualityBar||[]).map(x=>"- "+j(x)).join("\n")}\n\nRISKS & HOW WE HANDLE THEM\n${(p.risks||[]).map(x=>"- "+j(x)).join("\n")}\n\nSUPPORT & GUARANTEE\n${p.support||""}`;
  return ""; }
function bindAgentStudio(){ if(S.tab!=="agents") return; const m=document.querySelector(".agst"); if(!m) return;
  m.querySelector("[data-agname]").oninput=e=>{ AG.name=e.target.value; }; m.querySelector("[data-agbrief]").oninput=e=>{ AG.brief=e.target.value; };
  m.querySelector("[data-agnew]").onclick=()=>{ AG.sel=null; AG.pkg=null; AG.brief=""; AG.name=""; AG.sugg=[]; AG.qs=[]; AG.edits={}; AG.msg=""; render(); };
  m.querySelectorAll("[data-agopen]").forEach(b=>b.onclick=()=>{ const a=agList().find(x=>x.id===b.dataset.agopen); if(!a) return; AG.sel=a.id; AG.pkg=a.pkg||null; AG.brief=a.brief||""; AG.name=a.name||""; AG.sugg=[]; AG.qs=[]; AG.edits=a.edits||{}; AG.msg=""; render(); });
  m.querySelector("[data-agrefine]").onclick=agRefine; m.querySelector("[data-agbuild]").onclick=agBuild; const sv=m.querySelector("[data-agsave]"); if(sv) sv.onclick=()=>agSave(true); const ex=m.querySelector("[data-agexport]"); if(ex) ex.onclick=agExport;
  m.querySelectorAll("[data-agsrc]").forEach(c=>c.onchange=()=>{ AG.ideaSrc[c.dataset.agsrc]=c.checked; }); const gi=m.querySelector("[data-agideas]"); if(gi) gi.onclick=agIdeas;
  m.querySelectorAll("[data-aguse]").forEach(b=>b.onclick=()=>{ const x=AG.ideas[+b.dataset.aguse]; if(!x) return; AG.name=x.name||""; AG.brief=`${x.oneLiner||""}\nCustomers: ${x.who||""}\nWhy now: ${x.whyNow||""}\nFirst version: ${x.firstStep||""}`; AG.sel=null; AG.pkg=null; AG.edits={}; render(); window.scrollTo({top:0,behavior:"smooth"}); });
  m.querySelectorAll("[data-agdrop]").forEach(b=>b.onclick=()=>{ AG.ideas.splice(+b.dataset.agdrop,1); render(); });
  m.querySelectorAll("[data-agstart]").forEach(b=>b.onclick=()=>{ const x=AG_STARTERS[+b.dataset.agstart]; AG.name=x[0]; AG.brief=x[1]; render(); });
  m.querySelectorAll("[data-agadd]").forEach(b=>b.onclick=()=>{ const s=AG.sugg[+b.dataset.agadd]; if(!s) return; AG.brief=(AG.brief.trim()+"\n- "+s).trim(); AG.sugg.splice(+b.dataset.agadd,1); render(); });
  m.querySelectorAll("[data-agtab]").forEach(b=>b.onclick=()=>{ AG.tab=b.dataset.agtab; render(); });
  m.querySelectorAll("[data-agsec]").forEach(t=>t.oninput=()=>{ AG.edits[t.dataset.agsec]=t.value; });
  m.querySelectorAll("[data-agregen]").forEach(b=>b.onclick=()=>agRegen(b.dataset.agregen));
  m.querySelectorAll("[data-agship]").forEach(b=>b.onclick=()=>agShip(b.dataset.agship)); }
function agGround(){ let g=""; try{ if(S.playbook) g+="Aaron's SEO playbook (ground any SEO skill in it): "+JSON.stringify(S.playbook).slice(0,2500)+"\n"; const tr=S.knowledge&&S.knowledge.training&&Array.isArray(S.knowledge.training.items)?S.knowledge.training.items.filter(x=>x&&x.preferred).slice(0,8):[]; if(tr.length) g+="Preferred training docs: "+JSON.stringify(tr).slice(0,1500)+"\n"; }catch{} return g?g+"SKILLS MUST BE REAL: every skill carries the actual rules of that craft (specific, current, with numbers and limits), the exact verbiage/templates the agent uses, self-checks, and the top tools for that subject.\n":"SKILLS MUST BE REAL: every skill carries the actual rules of that craft (specific, current, with numbers and limits), the exact verbiage/templates the agent uses, self-checks, and the top tools for that subject.\n"; }
function agCtx(){ return `Aaron Lewis runs Elevated Designs (graphic tees), Charleston 3D Prints and three YouTube channels from Charleston, SC, with a team of AI agents on scheduled runs (Claude). He wants to build AI agents he can SELL as products — the bar is an agent good enough that a stranger pays for it monthly and keeps paying. Be concrete, honest and specific; no hype. Name real channels, real price points, real competitors where you know them. Never promise income; show the math instead.`; }
function agOpsContext(){ try{ const ag=Object.values(S.agents||{}).map(a=>a&&(a.name+": "+(a.role||"")+(a.lastSummary?" — last: "+String(a.lastSummary).slice(0,120):""))).filter(Boolean).slice(0,24); const pages="Console pages: Maker (photo→light box/keychain/sign/lithophane 3MF), Quick post (art→mockups→SEO copy→live listing), Pick & post, Store control (what's live on Shopify/Etsy, take off/put on), Design Lab (chat→image generation), Shirt designer, Design library (E-drive scan with thumbnails), Trend desk (breaking news→YouTube channels), SEO & knowledge (editable playbook, keywords, sources), Schedules (agent team), System map, Code (GitHub mirror), Agent Studio."; return "AARON'S OPERATION TODAY — agents: "+ag.join(" | ")+". "+pages; }catch{ return ""; } }
function agResearchContext(){ try{ const out=[]; if(S.news&&S.news.items) out.push("Lab Daily: "+JSON.stringify(S.news.items.slice(0,12)).slice(0,1500)); if(Array.isArray(S.sellers)&&S.sellers.length) out.push("Shirt sellers seen: "+S.sellers.slice(0,10).map(x=>x.name||x.title).join(", ")); if(S.trenddesk) out.push("Trend desk: "+JSON.stringify(S.trenddesk).slice(0,800)); if(S.seoKeywords&&S.seoKeywords.length) out.push("Keywords: "+S.seoKeywords.slice(0,20).map(k=>k.keyword||k.k||k).join(", ")); if(S.knowledge&&S.knowledge.training) out.push("Training docs: "+JSON.stringify(S.knowledge.training.items||[]).slice(0,800)); return out.join("\n").slice(0,4000); }catch{ return ""; } }
async function agIdeas(){ if(!sample){ toast("Open the console in Claude to use the studio."); return; } AG.busy="ideas"; render(); const src=AG.ideaSrc; const seen=AG.ideas.map(x=>x.name).join(", ");
  try{ const j=await sample.json(`${agCtx()}\nGenerate 8 ideas for AI agents Aaron could BUILD AND SELL (monthly subscription or done-for-you). Sources to draw on (only the ticked ones): ${src.hot?"HOT MARKETS — what small businesses and creators are paying for right now (AI agents, automation, e-commerce ops, local services, content) as of late 2026; ":""}${src.ops?"HIS OWN OPERATION — turn pieces of what he already runs into products other businesses would pay for: "+agOpsContext()+"; ":""}${src.research?"HIS RESEARCH — "+agResearchContext()+"; ":""}\n${seen?"Already suggested (don't repeat): "+seen+".":""}\nMix sizes: some he could launch THIS MONTH from what exists, some bigger. Each idea must name a specific buyer and the pain they already pay to solve. Reply with JSON only: {"ideas":[{"name":"","oneLiner":"what it does, in one sentence","who":"exact buyer","whyNow":"","source":"hot|ops|research","sellability":1-5,"priceHint":"$/mo","firstStep":"what the first version is, buildable from today's tools"}]}`,{modelTier:"default"});
    const list=Array.isArray(j&&j.ideas)?j.ideas:[]; AG.ideas=[...list,...AG.ideas].slice(0,24); if(!list.length) AG.msg="No ideas came back — try again."; try{ if(db&&list.length){ const now=new Date().toISOString(); for(const x of list.slice(0,8)) db.collection("agentideas").add({...x, at:now, by:"studio", status:"new"}).catch(()=>{}); } }catch{} }
  catch(e){ AG.msg=e&&e.code==="not_granted"?"Allow the console to ask Claude, then try again.":"Couldn't generate ideas right now."; }
  AG.busy=""; render(); }
async function agRefine(){ if(!sample){ toast("Open the console in Claude to use the studio."); return; } if(!AG.brief.trim()){ toast("Write a sentence or two first."); return; } AG.busy="refine"; AG.msg=""; render();
  try{ const j=await sample.json(`${agCtx()}\nAaron's draft for a sellable agent${AG.name?` called "${AG.name}"`:""}:\n"""${AG.brief}"""\nReply with JSON only: {"questions":[3-5 short questions whose answers would make this agent clearly better or more sellable],"suggestions":[6-10 concrete one-line additions he could add to the brief: capabilities, guardrails, a sharper customer, a report format, an upsell, a data source — each specific to THIS agent],"refined":"a 3-6 sentence tightened version of his brief in plain words, keeping everything he said","nameIdeas":["3 short product names"]}`,{modelTier:"default"});
    AG.qs=Array.isArray(j.questions)?j.questions.slice(0,5):[]; AG.sugg=Array.isArray(j.suggestions)?j.suggestions.slice(0,10):[]; if(j.refined&&typeof j.refined==="string") AG.brief=j.refined; if(!AG.name&&Array.isArray(j.nameIdeas)&&j.nameIdeas[0]) AG.name=String(j.nameIdeas[0]); AG.msg=Array.isArray(j.nameIdeas)?"Name ideas: "+j.nameIdeas.join(" · "):""; }
  catch(e){ AG.msg=e&&e.code==="not_granted"?"Allow the console to ask Claude, then try again.":"Couldn't refine right now."; }
  AG.busy=""; render(); }
const AG_SCHEMA=`{"name":"","tagline":"one line","verdict":"2-3 honest sentences: how sellable this is, what it would really take, and the realistic monthly revenue range for a solo founder in year one","agent":{"systemPrompt":"the complete instructions for the agent, 300-700 words, second person, with sections: role, every run, rules, output format, what it never does","tools":["tool/access it needs and why"],"schedule":"when it runs (cron in plain words) and why","inputs":["what the customer gives it"],"outputs":["exactly what the customer receives, with format"],"guardrails":["hard rules"]},"skills":[{"name":"one skill the agent needs, e.g. Etsy SEO","why":"","rules":["the actual rules of this craft, specific and current — numbers, limits, what ranks, what gets penalised"],"steps":["the step-by-step the agent follows every time"],"verbiage":["exact phrasing templates, formulas and examples it uses (titles, tags, replies, reports)"],"checks":["how it verifies its own output before delivering"],"tools":["top tool — free/paid — what it is used for"]}],"niche":{"who":"the precise buyer","pain":"the pain and its cost today","size":"rough number of buyers and how you know","whyNow":"","competitors":["name — what they charge — gap"],"edge":"why this wins"},"pricing":{"tiers":["Name — $/mo — what's included — who it's for"],"math":"customers x price needed for $100k/yr and for $100k/mo, churn assumptions, and whether the niche can hold that many","cost":"API/run cost per customer per month"},"monetization":["other revenue: setup fees, done-for-you, affiliate, white-label, data"],"listing":{"title":"","pitch":"120-180 words","bullets":["6 benefit bullets"],"proof":"what demo/proof to show","faq":["Q — A"],"where":["marketplace/site — why"]},"gtm":{"firstCustomers":["where the first 10 come from, specifically"],"channels":["channel — tactic — cost"],"launchPlan":["day-by-day or week-by-week steps for 30 days"],"content":["posts/videos/demos to make"]},"qualityBar":["measurable checks before it ships"],"risks":["risk — mitigation"],"support":"support and guarantee policy"}`;
async function agBuild(){ if(!sample){ toast("Open the console in Claude to use the studio."); return; } if(!AG.brief.trim()){ toast("Write the brief first."); return; } AG.busy="build"; AG.msg=""; render();
  try{ const j=await sample.json(`${agCtx()}\n${agGround()}Build the complete sellable-agent package for this brief${AG.name?` (working name "${AG.name}")`:""}:\n"""${AG.brief}"""\n${AG.pkg&&AG.pkg.field?"FIELD RESEARCH from the team (use it: match the must-have skills, build on the open-source pieces named, beat the competitors on their gaps):\n"+JSON.stringify(AG.pkg.field).slice(0,5000)+"\n":""}Reply with JSON only, exactly this shape (fill every field, arrays of strings):\n${AG_SCHEMA}`,{modelTier:"complex"});
    if(!j||typeof j!=="object"||!j.agent) throw new Error("bad"); if(AG.pkg){ if(AG.pkg.field) j.field=AG.pkg.field; if(AG.pkg.research) j.research=AG.pkg.research; } AG.pkg=j; AG.edits={}; if(j.name&&!AG.name) AG.name=String(j.name); AG.tab="agent"; AG.msg="Package built."; await agSave(false); }
  catch(e){ AG.msg=e&&e.code==="not_granted"?"Allow the console to ask Claude, then try again.":"Couldn't build the package. Try again."; }
  AG.busy=""; render(); }
async function agRegen(k){ if(!sample||!AG.pkg) return; AG.busy="regen"; render(); const keys={agent:"agent",skills:"skills (every skill: rules of the craft, steps, verbiage/templates, self-checks, top tools — deeper and more specific)",niche:"niche",pricing:"pricing (and monetization)",listing:"listing",gtm:"gtm",quality:"qualityBar, risks and support"}[k]||k;
  try{ const j=await sample.json(`${agCtx()}\nBrief: """${AG.brief}"""\nCurrent package: ${JSON.stringify(AG.pkg).slice(0,6000)}\nAaron's own edits to this part (keep them; they win): """${AG.edits[k]||""}"""\nRegenerate ONLY the ${keys} part, better and more specific. Reply with JSON only, same shape as the full package but containing only the keys for that part.`,{modelTier:"complex"});
    if(j&&typeof j==="object"){ Object.assign(AG.pkg,j); delete AG.edits[k]; AG.msg="Updated."; await agSave(false); } }
  catch{ AG.msg="Couldn't regenerate."; }
  AG.busy=""; render(); }
async function agSave(say){ if(!db) return; const now=new Date().toISOString(); const data={name:AG.name||(AG.pkg&&AG.pkg.name)||"Untitled agent", brief:AG.brief, pkg:AG.pkg, edits:AG.edits, updatedAt:now, by:"aaron"};
  try{ if(AG.sel){ await db.doc("agentproducts/"+AG.sel).update(data); } else { const r=await db.collection("agentproducts").add({...data, at:now, stage:"idea"}); AG.sel=r.id; } if(say) toast("Saved."); }catch{ if(say) toast("Couldn't save."); } }
function agExport(){ if(!AG.pkg) return; const md=`# ${AG.name||AG.pkg.name}\n\n${AG.pkg.tagline||""}\n\n> ${AG.pkg.verdict||""}\n\n## Brief\n${AG.brief}\n\n`+AG_SECTIONS.map(([k,l])=>`## ${l}\n${AG.edits[k]!==undefined?AG.edits[k]:agText(AG.pkg,k)}\n`).join("\n"); const blob=new Blob([md],{type:"text/markdown"}); if(typeof codeDownload==="function") codeDownload(blob,(AG.name||"agent").replace(/[^\w.-]+/g,"-")+".md"); }
async function agShip(kind){ if(!agCan()||!db||!AG.pkg) return; await agSave(false); const name=AG.name||AG.pkg.name||"Agent"; const now=new Date().toISOString(); const txt=(k)=>AG.edits[k]!==undefined?AG.edits[k]:agText(AG.pkg,k);
  try{ if(kind==="build"){ const ref=await db.collection("requests").add({for:"max", by:"aaron", status:"open", at:now, agentProduct:AG.sel, approval:"Aaron approved building this agent from Agent Studio on "+now.slice(0,10), what:`BUILD AGENT "${name}" as a new scheduled task (Console builder job). Use agentproducts/${AG.sel} — the "agent" section below is the system prompt, tools, schedule and guardrails. Create the scheduled task with the SECURITY block every agent has, the dashboard conventions (activity, huddle, requests), and the schedule given; run it once in test mode (no customer-facing output) and report what it produced.\n\n${txt("agent")}`});
      await db.doc("agentproducts/"+AG.sel).update({stage:"building",buildRequest:ref.id}); const tid=typeof tidOf==="function"?(tidOf("console")||"trig_01F9MQZmGhryuqF4TaPj9LG1"):null; if(tid) await fire(tid,`BUILD AGENT request from Aaron: requests/${ref.id} — create the scheduled task described there (agentproducts/${AG.sel}), test-run it, report.`); AG.msg="Sent to be built. It shows under Schedules when it exists."; }
    else if(kind==="field"){ const ref=await db.collection("requests").add({for:"nora", by:"aaron", status:"open", at:now, agentProduct:AG.sel, what:`FIELD RESEARCH for agent product "${name}" (agentproducts/${AG.sel}). Brief: ${AG.brief.slice(0,1500)}\n1) Find the top 8-12 agents/products already sold in this space (companies, indie makers, marketplaces like the GPT store, Zapier/Make templates, Relevance, Lindy, CrewAI/LangGraph showcases): name, url, price, what it does, what customers praise and complain about. 2) List the skills every winner has (the must-haves) and the gaps. 3) Find open-source code we can legally build on: GitHub repos, agent frameworks, skills and prompt libraries whose licence permits commercial use (MIT, Apache-2.0, BSD, MPL; NOT GPL/AGPL for code we ship, NOT proprietary) — for each: name, url, licence, stars, what exactly to reuse. 4) Write agentproducts/${AG.sel}.field {products:[], skills:[], repos:[{name,url,license,stars,reuse}], plan:"what we take and what we do better"} and hand Sam the repo list: Sam clones each permitted repo, reads it, extracts the reusable pieces into a folder agents/${(name||"agent").toLowerCase().replace(/[^a-z0-9]+/g,"-")}/ in the Business-console repo (with LICENSE files and attribution kept), and appends {sam:{reviewed:[], kept:[], notes}} to the same field doc. Tell Stephanie in one line when done.`}); const tid=typeof tidOf==="function"?tidOf("nora"):null; if(tid) await fire(tid,`FIELD RESEARCH request from Aaron: requests/${ref.id} — do it now, then hand the repos to Sam (fire him).`); AG.msg="Nora is researching the field; Sam pulls the code. It lands under Field research."; }
    else if(kind==="research"){ const ref=await db.collection("requests").add({for:"nora", by:"aaron", status:"open", at:now, agentProduct:AG.sel, what:`VALIDATE NICHE for agent product "${name}" (agentproducts/${AG.sel}). Check the buyer, the pain, the market size claim, competitors and prices against real sources; find 10 real places these buyers gather; write agentproducts/${AG.sel}.research {findings, sources, verdict} and tell Stephanie in one line.\n\n${txt("niche")}\n\n${txt("pricing")}`}); const tid=typeof tidOf==="function"?tidOf("nora"):null; if(tid) await fire(tid,`NICHE VALIDATION request from Aaron: requests/${ref.id}.`); AG.msg="Nora is validating the niche."; }
    else { const ref=await db.collection("requests").add({for:"tina", by:"aaron", status:"open", at:now, agentProduct:AG.sel, what:`LAUNCH agent product "${name}" (agentproducts/${AG.sel}): Tina builds the launch content and posts from the GTM plan; Carla builds the listing/landing page from the listing section (Shopify digital product or the site Sam picks) with SEO; both report links to Stephanie.\n\n${txt("listing")}\n\n${txt("gtm")}`}); await db.doc("agentproducts/"+AG.sel).update({stage:"launching"}); for(const k of ["tina","carla"]){ const tid=typeof tidOf==="function"?tidOf(k):null; if(tid) await fire(tid,`AGENT LAUNCH request from Aaron: requests/${ref.id} (your part only).`); } AG.msg="Tina and Carla have the launch."; }
    toast("Sent."); }
  catch{ AG.msg="Couldn't send that."; }
  render(); }

/* ================= PAPERWORK: every document behind the legal/tax/setup to-do list — ready to download, sign, upload back, and mirrored to the desktop ================= */
const PW={busy:new Set(), open:null};
const PW_STAT={drafting:["Helen is drafting",""],ready:["Ready to sign","warn"],signed:["Signed · Helen reviewing","acc"],filed:["Filed · done","ok"],needs:["Needs you","bad"]};
function pwRef(ref){ const [c,id]=String(ref||"").split("/"); const x=({legal:S.legal,tax:S.tax,setup:S.setup,matter:S.matters})[c]||[]; return (x||[]).find(i=>i.id===id)||null; }
function pwItems(){ return (S.paperwork||[]).slice().sort((a,b)=>{ const o={needs:0,ready:1,signed:2,drafting:3,filed:4}; return (o[a.status]??5)-(o[b.status]??5)||String(a.title).localeCompare(String(b.title)); }); }
/* items on the legal/tax/setup lists that have no paperwork yet but clearly need a document */
function pwMissing(){ const have=new Set((S.paperwork||[]).map(p=>p.forRef)); const out=[]; const needDoc=/licen|permit|form|agreement|contract|policy|terms|registration|ein|tax|w-9|1099|dba|operating|insurance|certificate|application|filing/i;
  S.legal.filter(x=>x.status!=="done"&&!have.has("legal/"+x.id)&&needDoc.test(x.title+" "+(x.note||""))).forEach(x=>out.push({ref:"legal/"+x.id,title:x.title}));
  (S.tax||[]).filter(x=>x.status!=="done"&&!have.has("tax/"+x.id)&&needDoc.test(x.title+" "+(x.note||""))).forEach(x=>out.push({ref:"tax/"+x.id,title:x.title}));
  S.setup.filter(x=>!x.done&&!have.has("setup/"+x.id)&&needDoc.test(x.title+" "+(x.why||""))).forEach(x=>out.push({ref:"setup/"+x.id,title:x.title}));
  return out; }
function paperworkCard(){ const items=pwItems(); const missing=pwMissing(); const own=qpCan();
  return `<section class="card" id="paperwork"><div class="card-head"><h2 class="big">Paperwork</h2><span class="eyebrow">${items.length?`${items.filter(p=>p.status==="ready"||p.status==="needs").length} waiting on you · ${items.length} total`:"every document, one place"}</span></div>
    <p class="small muted" style="margin-top:0">Every form, license application, agreement and policy behind your to-do list, as a real file: download the Word or PDF, sign it, then drop the signed or supporting copy back here. Helen reviews what you upload and moves the item on. Everything is also mirrored to <b>Desktop ▸ Elevated Designs Paperwork</b> on your PC.</p>
    ${own?`<div class="row" style="gap:8px;flex-wrap:wrap;margin-bottom:10px"><button type="button" class="btn" data-pwsync>Copy everything to my desktop now</button><button type="button" class="btn" data-pwall ${missing.length?"":"disabled"}>Ask Helen to draft the ${missing.length} missing document${missing.length===1?"":"s"}</button></div>`:""}
    ${items.length?`<div class="pwlist">${items.map(pwRow).join("")}</div>`:`<div class="empty">Nothing drafted yet. ${missing.length?"Tap the button above and Helen writes the first drafts on her next run.":"Helen adds documents here as legal and tax items come up."}</div>`}
    ${missing.length?`<details style="margin-top:10px"><summary class="small muted">${missing.length} to-do item${missing.length===1?"":"s"} without a document yet</summary><ul class="small">${missing.map(m=>`<li>${esc(m.title)} ${own?`<button type="button" class="linkbtn" data-pwask="${esc(m.ref)}">ask Helen</button>`:""}</li>`).join("")}</ul></details>`:""}</section>`; }
function pwRow(p){ const st=PW_STAT[p.status]||[p.status||"",""]; const link=pwRef(p.forRef); const files=[["docx","Word",p.docx],["pdf","PDF",p.pdf]].filter(x=>x[2]&&x[2].assetId); const ups=Array.isArray(p.uploads)?p.uploads:[]; const open=PW.open===p.id; const busy=PW.busy.has(p.id);
  return `<div class="pwrow ${open?"open":""}"><div class="pwhead" data-pwopen="${esc(p.id)}"><div class="stripe ${st[1]}"></div><div class="body"><div class="t">${esc(p.title)}</div><div class="meta">${link?esc(link.title||link.what||""):esc(p.forRef||"")}${p.due?" · due "+esc(p.due):""}${p.nextStep?" · <b>"+esc(p.nextStep)+"</b>":""}</div></div><span class="pill ${st[1]}">${esc(st[0])}</span></div>
    ${open?`<div class="pwbody">${p.what?`<p class="small">${esc(p.what)}</p>`:""}${p.howTo?`<div class="note small"><b>What to do:</b> ${esc(p.howTo)}</div>`:""}
      <div class="row" style="gap:8px;flex-wrap:wrap;margin-top:8px">${files.map(f=>`<button type="button" class="btn" data-pwdl="${esc(p.id)}" data-fmt="${f[0]}" ${busy?"disabled":""}>Download ${f[1]}</button>`).join("")||`<span class="small muted">${p.status==="drafting"?"Helen is still writing this one.":"No file attached yet."}</span>`}${p.officialUrl?`<a class="btn" href="${esc(safeUrl(p.officialUrl))}" target="_blank" rel="noopener">Official form / site</a>`:""}</div>
      <div class="pwups"><b class="small">Signed & supporting documents</b>${ups.length?`<ul class="small">${ups.map(u=>`<li>${esc(u.name||"file")} · ${esc(String(u.at||"").slice(0,10))}${u.assetId?` · <button type="button" class="linkbtn" data-pwget="${esc(u.assetId)}" data-name="${esc(u.name||"file")}">open</button>`:""}</li>`).join("")}</ul>`:`<p class="small muted">Nothing uploaded yet.</p>`}
        ${qpCan()?`<label class="btn pwupl">${busy?"Uploading…":"Upload signed or supporting file"}<input type="file" data-pwup="${esc(p.id)}" accept=".pdf,.docx,.doc,.jpg,.jpeg,.png,.heic" multiple hidden ${busy?"disabled":""}></label>${p.status!=="filed"?`<button type="button" class="btn" data-pwfiled="${esc(p.id)}">Mark as filed / done</button>`:""}`:""}</div></div>`:""}</div>`; }
function bindPaperwork(){ document.querySelectorAll("[data-pwopen]").forEach(h=>h.onclick=()=>{ PW.open=PW.open===h.dataset.pwopen?null:h.dataset.pwopen; render(); });
  document.querySelectorAll("[data-pwdl]").forEach(b=>b.onclick=()=>pwDownload(b.dataset.pwdl,b.dataset.fmt)); document.querySelectorAll("[data-pwget]").forEach(b=>b.onclick=()=>pwFetch(b.dataset.pwget,b.dataset.name));
  document.querySelectorAll("[data-pwup]").forEach(i=>i.onchange=()=>pwUpload(i.dataset.pwup,i.files)); document.querySelectorAll("[data-pwfiled]").forEach(b=>b.onclick=()=>pwFiled(b.dataset.pwfiled));
  document.querySelectorAll("[data-pwask]").forEach(b=>b.onclick=()=>pwAsk([b.dataset.pwask])); const all=document.querySelector("[data-pwall]"); if(all) all.onclick=()=>pwAsk(pwMissing().map(m=>m.ref));
  const sy=document.querySelector("[data-pwsync]"); if(sy) sy.onclick=async()=>{ const tid=typeof tidOf==="function"?(tidOf("library")||"trig_01TPs3sD9Cyg8dLvzJ7AHbzz"):null; if(!tid){ toast("The desktop sync task isn't loaded yet."); return; } sy.disabled=true; const ok=await fire(tid,`PAPERWORK SYNC requested by Aaron from the console: copy every paperwork file (drafts, PDFs and uploads) to Desktop\\Elevated Designs Paperwork on NUC_SKULL now, then stop.`); toast(ok?"Copying to your desktop.":"Queued for the next sync."); }; }
async function pwFetch(assetId,name){ try{ const r=await fetch("/_blob/"+assetId); if(!r.ok) throw new Error("x"); const b=await r.blob(); if(downloads){ try{ await downloads.save({filename:name||"document",data:b}); return; }catch(e){ if(e&&e.code==="cancelled") return; } } const a=document.createElement("a"); a.href=URL.createObjectURL(b); a.download=name||"document"; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },4000); }catch{ toast("Couldn't open that file. Try from Claude."); } }
async function pwDownload(id,fmt){ const p=(S.paperwork||[]).find(x=>x.id===id); if(!p) return; const f=p[fmt]; if(!f||!f.assetId) return; await pwFetch(f.assetId,f.name||(dslugLike(p.title)+"."+fmt)); }
function dslugLike(t){ return String(t||"document").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,60); }
async function pwUpload(id,files){ const p=(S.paperwork||[]).find(x=>x.id===id); const fs=[...(files||[])]; if(!p||!fs.length||!assets||!db) return; PW.busy.add(id); render();
  try{ const now=new Date().toISOString(); const ups=Array.isArray(p.uploads)?p.uploads.slice():[]; for(const f of fs){ if(f.size>20*1048576){ toast(f.name+" is over 20 MB"); continue; } const a=await assets.upload(f); ups.push({assetId:a.id,name:f.name,bytes:f.size,at:now,by:"aaron"}); }
    await db.doc("paperwork/"+id).update({uploads:ups, status:p.status==="filed"?"filed":"signed", nextStep:"Helen reviews the upload", updatedAt:now});
    await db.collection("requests").add({for:"helen", by:"aaron", status:"open", at:now, what:`PAPERWORK UPLOAD: Aaron uploaded ${fs.length} file${fs.length===1?"":"s"} for "${p.title}" (paperwork/${id}). Review them (Artifact read, path = assetId), confirm they're complete and signed where needed, set the paperwork status (filed if it's done, needs if something is missing with a one-line nextStep), update the linked item ${p.forRef||""}, and tell Stephanie in one line.`});
    const tid=typeof tidOf==="function"?tidOf("helen"):null; if(tid) fire(tid,`PAPERWORK UPLOAD from Aaron on paperwork/${id} — review it now.`); toast("Uploaded. Helen is reviewing."); }
  catch{ toast("Couldn't upload. Try again."); }
  PW.busy.delete(id); render(); }
async function pwFiled(id){ if(!db) return; try{ await db.doc("paperwork/"+id).update({status:"filed", nextStep:"", filedAt:new Date().toISOString(), filedBy:"aaron"}); toast("Marked as filed."); }catch{ toast("Couldn't save that."); } }
async function pwAsk(refs){ if(!db||!refs.length) return; try{ const now=new Date().toISOString(); const names=refs.map(r=>{ const x=pwRef(r); return (x&&(x.title||x.what))||r; });
    const ref=await db.collection("requests").add({for:"helen", by:"aaron", status:"open", at:now, what:`PAPERWORK DRAFTS: Aaron wants the actual documents for these to-do items, ready to download, sign and file: ${refs.map((r,i)=>`${names[i]} (${r})`).join("; ")}. For each: write the document (Word .docx and a PDF of it) or, for a government form that can't be generated, a filled-in cover sheet with every answer he should enter plus the official form link; upload both files as assets and create paperwork/<id> {title, forRef, what, howTo, status:"ready", docx:{assetId,name}, pdf:{assetId,name}, officialUrl, due, uploads:[]}. Never put his SSN, EIN, card or account numbers in any document — leave labelled blanks.`});
    const tid=typeof tidOf==="function"?tidOf("helen"):null; if(tid) await fire(tid,`PAPERWORK DRAFTS request from Aaron: requests/${ref.id} — draft them this run.`); toast(`Helen is drafting ${refs.length} document${refs.length===1?"":"s"}.`); render(); }catch{ toast("Couldn't send that."); } }

/* ================= EXPORT, everywhere: one menu, the formats that make sense for the page you're on ================= */
const XM={items:[]};
const DL_OK=/\.(gif|png|jpe?g|webp|mp4|webm|txt|json|md|docx|pptx|epub|csv|ttf|html|svg|pdf|xlsx|zip)$/i;
/* one download path for the whole console: files the viewer can't take directly (.3mf, .stl, .js…) are wrapped in a .zip */
async function dlBlob(name,blob){ name=String(name||"file").replace(/[\\/:*?"<>|]+/g,"-");
  if(!DL_OK.test(name)&&typeof mkZip==="function"){ const data=new Uint8Array(await blob.arrayBuffer()); blob=new Blob([mkZip([{name,data}])],{type:"application/zip"}); name=name.replace(/\.[^.]+$/,"")+".zip"; }
  if(typeof downloads!=="undefined"&&downloads){ try{ await downloads.save({filename:name,data:blob}); return true; }catch(e){ const c=e&&e.code; if(c==="declined"||c==="cancelled") return false; if(c==="rate_limited"){ toast("A save box is already open. Finish that one first."); return false; } if(c==="too_large"){ toast("That file is too big to save here."); return false; } console.error("download",c,e); } }
  try{ dlFallback(name,blob); return true; }catch{ toast("Couldn't download it. Open the console in the Claude app and try again."); return false; } }
function dlFallback(name,blob){ const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=name; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },4000); }
function dlText(name,text,mime){ dlBlob(name,new Blob([text],{type:mime||"text/plain"})); }
function csvOf(rows,cols){ if(!rows.length) return ""; cols=cols||[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(k=>!/^(html|history|log)$/.test(k)); const q=v=>{ if(v==null) return ""; if(typeof v==="object") v=JSON.stringify(v); v=String(v); return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v; }; return cols.join(",")+"\n"+rows.map(r=>cols.map(c=>q(r[c])).join(",")).join("\n"); }
function mdOf(title,rows,cols){ cols=cols||[...new Set(rows.flatMap(r=>Object.keys(r)))].slice(0,8); return `# ${title}\n\n| ${cols.join(" | ")} |\n| ${cols.map(()=>"---").join(" | ")} |\n`+rows.map(r=>`| ${cols.map(c=>String(r[c]??"").replace(/\|/g,"/").replace(/\n/g," ").slice(0,120)).join(" | ")} |`).join("\n")+"\n"; }
function stamp(){ return new Date().toISOString().slice(0,10); }
function shopifyCsv(L){ return csvOf(L.map(l=>({Handle:String(l.title||l.id||"").toLowerCase().replace(/[^a-z0-9]+/g,"-").slice(0,60),Title:l.title||"","Body (HTML)":l.description||"",Vendor:listingBiz(l)==="c3d"?"Charleston 3D Prints":"Elevated Designs",Tags:(l.tags||[]).join(", "),Published:l.status==="posted"?"TRUE":"FALSE","Variant Price":l.price||"","Image Src":(l.photos&&l.photos[0]&&(l.photos[0].url||l.photos[0]))||"",Status:l.status||""})),["Handle","Title","Body (HTML)","Vendor","Tags","Published","Variant Price","Image Src","Status"]); }
function etsyCsv(L){ return csvOf(L.map(l=>({TITLE:String(l.title||"").slice(0,140),DESCRIPTION:l.description||"",PRICE:l.price||"",QUANTITY:l.quantity||10,TAGS:(l.tags||[]).slice(0,13).join(","),MATERIALS:l.materials||"",IMAGE1:(l.photos&&l.photos[0]&&(l.photos[0].url||l.photos[0]))||""})),["TITLE","DESCRIPTION","PRICE","QUANTITY","TAGS","MATERIALS","IMAGE1"]); }
function exportItems(){ const t=S.tab, b=S.biz||"ed", d=stamp(); const it=[]; const add=(label,fn)=>it.push({label,fn});
  const tbl=(name,rows,cols)=>{ add(`${name} · CSV`,()=>dlText(`${name.toLowerCase().replace(/\W+/g,"-")}-${d}.csv`,csvOf(rows,cols),"text/csv")); add(`${name} · JSON`,()=>dlText(`${name.toLowerCase().replace(/\W+/g,"-")}-${d}.json`,JSON.stringify(rows,null,2),"application/json")); add(`${name} · Markdown table`,()=>dlText(`${name.toLowerCase().replace(/\W+/g,"-")}-${d}.md`,mdOf(name,rows,cols),"text/markdown")); };
  const L=(S.listings||[]).filter(l=>listingBiz(l)===b), D=(S.designs||[]).filter(x=>designBiz(x)===b);
  switch(t){
    case "listings": add("Shopify import · CSV",()=>dlText(`shopify-${b}-${d}.csv`,shopifyCsv(L),"text/csv")); add("Etsy upload · CSV",()=>dlText(`etsy-${b}-${d}.csv`,etsyCsv(L),"text/csv")); tbl("Listings",L,["id","title","status","price","channel","tags","at"]); break;
    case "design": tbl("Designs",D,["id","title","brand","status","style","product","by","at"]); add("Design images · list of links",()=>dlText(`design-images-${b}-${d}.txt`,D.map(x=>`${x.title||x.id}\t${x.imageUrl||x.mockupUrl||""}`).join("\n"))); break;
    case "elevated": case "c3d": tbl("Listings",L,["id","title","status","price","channel","at"]); tbl("Designs",D,["id","title","status","style","product","at"]); break;
    case "research": case "rsettings": tbl("Research jobs",(S.research||[]).filter(r=>!r.removed),["id","agent","label","when","enabled","sources","queries","limits"]); break;
    case "apps": case "ideas": tbl("Apps",S.apps||[],["id","name","stage","owner","liveUrl","prototypeUrl","pitch"]); tbl("App ideas",S.appideas||[],["id","name","oneLiner","status","monetization"]); break;
    case "agents": tbl("Agent packages",S.agentproducts||[],["id","name","niche","price","status"]); break;
    case "code": add("This repo · zip",()=>{ if(typeof codeZip==="function") codeZip(); }); break;
    case "studio": { const Q=(S.queue||[]).filter(q=>/youtube/i.test(q.platform||"")); tbl("Video queue",Q,["id","platform","title","status","when","link","source"]); add("Titles + descriptions · TXT",()=>dlText(`youtube-copy-${d}.txt`,Q.map(q=>`${q.title}\n${q.caption||""}\n`).join("\n---\n"))); break; }
    case "money": tbl("Subscriptions & bills",(S.bills||[]).map(x=>({id:x.id,name:x.name,amount:x.amount,cadence:x.cadence,next:x.next||x.nextCharge,status:x.status,paidWith:x.paidWith,business:x.business})),["id","name","amount","cadence","next","status","paidWith","business"]); break;
    case "pricing": tbl("Pricing",(S.metrics||[]).filter(m=>/price|fee|margin/i.test(m.label||m.id||"")),["id","label","value","unit","note","source"]); break;
    case "legal": tbl("Legal & tax items",[...(S.legal||[]).map(x=>({kind:"legal",...x})),...(S.tax||[]).map(x=>({kind:"tax",...x}))],["kind","id","title","status","due","note"]); tbl("Paperwork",S.paperwork||[],["id","title","status","forRef","due","nextStep"]); add("Word / PDF of a document → ask Helen",()=>{ if(typeof pwAsk==="function") toast("Open a document above and use its Download Word / PDF buttons; Helen drafts any that are missing."); }); break;
    case "comms": case "team": tbl("Messages",S.messages||[],["id","from","to","subject","text","at"]); tbl("Requests",S.requests||[],["id","for","by","status","what","at"]); break;
    case "schedules": add("Schedules · JSON",()=>dlText(`schedules-${d}.json`,JSON.stringify(Object.values(S.triggers||{}).map(x=>({id:x.id,name:x.name,cron:x.cron_expression,enabled:x.enabled,next:x.next_run_at})),null,2),"application/json")); break;
    case "docs": tbl("Docs",S.docs||[],["id","title","kind","updatedAt"]); break;
    case "knowledge": tbl("SEO audit",S.seoaudit||[],["id","name","url","score","checkedAt"]); tbl("SEO track",S.seotrack||[],["id","date","slot","avgScore","summary"]); break;
    case "markets": tbl("Events",S.events||[],["id","title","date","venue","city","url"]); break;
    case "sellers": tbl("Shirt sellers",S.sellers||[],["id","name","city","platform","priceLow","priceHigh","url"]); break;
    case "print3d": tbl("3D trend datasets",(S.printtrends||[]).map(x=>({id:x.id,capturedAt:x.capturedAt,source:x.source,rows:(x.rows||[]).length})),["id","capturedAt","source","rows"]); break;
    case "lightbox": add("STL / 3MF → use the Download buttons in the Maker",()=>toast("Build a part first, then Download STL or 3MF.")); break;
    case "library": add("Design library · manifest JSON",()=>dlText(`library-manifest-${d}.json`,JSON.stringify(S.libManifest||{},null,2),"application/json")); break;
  }
  add("Everything on this page · JSON snapshot",()=>{ const snap={}; ["activity","designs","listings","apps","research","requests","queue","bills","legal","tax","paperwork","repos","agentproducts"].forEach(k=>{ if(S[k]) snap[k]=S[k]; }); dlText(`console-snapshot-${t}-${d}.json`,JSON.stringify(snap,null,2),"application/json"); });
  return it; }
function exportMenu(){ XM.items=exportItems(); if(!XM.items.length) return "";
  return `<details class="xmenu"><summary class="ptab xbtn">Export ▾</summary><div class="xpop">${XM.items.map((x,i)=>`<button type="button" data-xm="${i}">${esc(x.label)}</button>`).join("")}</div></details>`; }
function bindExportMenu(){ document.querySelectorAll("[data-xm]").forEach(b=>b.onclick=()=>{ const x=XM.items[+b.dataset.xm]; const dt=b.closest("details"); if(dt) dt.open=false; if(x) try{ x.fn(); toast("Exporting…"); }catch(e){ console.error(e); toast("Couldn't export that."); } }); }

/* ================= IN-PAGE DIALOGS: the published page runs in a sandbox where the browser's confirm()/prompt() boxes are blocked and silently say "no", so every question is asked in the page itself ================= */
function hqDialog({title="", body="", fields=[], ok="OK", cancel="Cancel", danger=false}){
  return new Promise(res=>{
    const prev=document.activeElement; const wrap=document.createElement("div"); wrap.className="hqdlg-wrap";
    wrap.innerHTML=`<div class="hqdlg" role="dialog" aria-modal="true" aria-labelledby="hqdlgT">${title?`<h2 id="hqdlgT">${esc(title)}</h2>`:""}${body?`<p class="hqdlg-b">${esc(body).replace(/\n/g,"<br>")}</p>`:""}
      ${fields.map((f,i)=>`<label class="hqdlg-f"><span>${esc(f.label||"")}</span>${f.multi?`<textarea data-hqf="${i}" rows="3">${esc(f.value||"")}</textarea>`:`<input type="text" data-hqf="${i}" value="${esc(f.value||"")}" placeholder="${esc(f.placeholder||"")}">`}</label>`).join("")}
      <div class="hqdlg-a">${cancel?`<button type="button" class="btn" data-hqno>${esc(cancel)}</button>`:""}<button type="button" class="btn ${danger?"danger":"primary"}" data-hqok>${esc(ok)}</button></div></div>`;
    document.body.appendChild(wrap);
    const done=v=>{ wrap.remove(); document.removeEventListener("keydown",key,true); try{ prev&&prev.focus&&prev.focus(); }catch{} res(v); };
    const vals=()=>fields.map((_,i)=>{ const el=wrap.querySelector(`[data-hqf="${i}"]`); return el?el.value:""; });
    const key=e=>{ if(e.key==="Escape"){ e.preventDefault(); done(fields.length?null:false); } else if(e.key==="Enter"&&!(e.target&&e.target.tagName==="TEXTAREA")){ e.preventDefault(); done(fields.length?vals():true); } };
    document.addEventListener("keydown",key,true);
    wrap.addEventListener("click",e=>{ if(e.target.closest("[data-hqok]")) done(fields.length?vals():true); else if(e.target.closest("[data-hqno]")||e.target===wrap) done(fields.length?null:false); });
    setTimeout(()=>{ const f=wrap.querySelector("[data-hqf]")||wrap.querySelector("[data-hqok]"); f&&f.focus(); },0);
  }); }
function hqConfirm(body,{title="",ok="Yes",cancel="Cancel",danger=false}={}){ return hqDialog({title,body,ok,cancel,danger}); }
async function hqPrompt(label,value="",{title="",ok="Save",multi=false}={}){ const v=await hqDialog({title,fields:[{label,value,multi}],ok}); return v?v[0]:null; }

/* ================= MAKER APPS inside the console: Hype Chain Maker and Nameplate Maker run in a frame fed from console assets ================= */
const MAKER_APPS={
  hype:{name:"Hype Chain Maker",asset:"ad76dc3446de15eb901f72a94aa2c706",live:"https://epix3d.com",blurb:"Pendant from a logo or text, chain styles and lengths, LED channels, filament slots, Bambu-ready .3mf with preview card.",size:"0.4 MB"},
  nameplate:{name:"Nameplate Maker",asset:"d8184f317fe0f965e0bab04ecb197eef",live:"https://epix3d.com",blurb:"Multi-colour nameplates and desk signs: fonts, art frames, plates and panels, Bambu-ready .3mf.",size:"11.8 MB"}
};
const MK_APP={html:{},state:{},tall:false};
const MK_DL_BRIDGE=`<script>(function(){function send(a){try{var n=a.getAttribute("download")||"file";var h=a.href;if(!h)return false;if(/^data:/.test(h)||/^blob:/.test(h)){fetch(h).then(function(r){return r.blob()}).then(function(b){parent.postMessage({type:"hqmakerdl",name:n,blob:b},"*")});return true}}catch(e){}return false}var oc=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){if(this.hasAttribute("download")&&send(this))return;return oc.apply(this,arguments)};document.addEventListener("click",function(e){var a=e.target&&e.target.closest&&e.target.closest("a[download]");if(a&&send(a)){e.preventDefault();e.stopPropagation()}},true)})();<\/script>`;
function mkWithBridge(html){ return /<head[^>]*>/i.test(html)?html.replace(/<head[^>]*>/i,m=>m+MK_DL_BRIDGE):MK_DL_BRIDGE+html; }

function vMakerApp(key){ const a=MAKER_APPS[key]; if(!a) return vOverview(); const st=MK_APP.state[key]||"idle";
  return `<section class="card mkapp ${MK_APP.tall?"tall":""}"><div class="card-head"><h2 class="big">${esc(a.name)}</h2><span class="eyebrow">${esc(a.blurb)}</span></div>
    <div class="row" style="gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:8px"><button type="button" class="btn" data-mkfull>${MK_APP.tall?"Normal size":"Full height"}</button><button type="button" class="btn" data-mkreload="${key}">Reload</button><button type="button" class="btn" data-mkopen="${key}">Open in its own tab ↗</button><button type="button" class="btn" data-goto="code">Source in Code</button><span class="small muted">Downloads save to your computer as usual · ${esc(a.size)} loads once, then it's cached.</span></div>
    <div class="mkframe" data-mkframe="${key}">${st==="ready"?"":st==="error"?`<div class="empty">Couldn't load the app. Tap Reload to try again.</div>`:`<div class="empty"><span class="spin"></span> Loading ${esc(a.name)}…</div>`}</div></section>`; }
async function mkAppLoad(key){ const a=MAKER_APPS[key]; const box=document.querySelector(`[data-mkframe="${key}"]`); if(!a||!box) return;
  if(box.querySelector("iframe")||MK_APP.state[key]==="error"||MK_APP.state[key]==="loading") return;
  try{ if(!MK_APP.html[key]){ MK_APP.state[key]="loading"; const r=await fetch("/_blob/"+a.asset); if(!r.ok) throw new Error("HTTP "+r.status); MK_APP.html[key]=await r.text(); }
    const f=document.createElement("iframe"); f.className="mkif"; f.title=a.name; f.setAttribute("allow","clipboard-write; fullscreen"); f.srcdoc=mkWithBridge(MK_APP.html[key]); box.innerHTML=""; box.appendChild(f); MK_APP.state[key]="ready"; }
  catch(e){ console.error("maker app",e); MK_APP.state[key]="error"; render(); } }
function bindMakerApps(){ const key=S.tab==="hype"?"hype":S.tab==="nameplate"?"nameplate":null; if(!key) return; mkAppLoad(key);
  const fb=document.querySelector("[data-mkfull]"); if(fb) fb.onclick=()=>{ MK_APP.tall=!MK_APP.tall; const c=document.querySelector(".mkapp"); if(c) c.classList.toggle("tall",MK_APP.tall); fb.textContent=MK_APP.tall?"Normal size":"Full height"; };
  const ob=document.querySelector("[data-mkopen]"); if(ob) ob.onclick=async()=>{ const k=ob.dataset.mkopen, a=MAKER_APPS[k]; const w=window.open("","_blank"); try{ if(!MK_APP.html[k]){ const r=await fetch("/_blob/"+a.asset); if(!r.ok) throw 0; MK_APP.html[k]=await r.text(); } const u=URL.createObjectURL(new Blob([MK_APP.html[k]],{type:"text/html"})); if(w) w.location=u; else window.open(u,"_blank"); }catch{ if(w) w.close(); toast("Couldn't open it. Use it here instead."); } };
  const rb=document.querySelector("[data-mkreload]"); if(rb) rb.onclick=()=>{ const f=document.querySelector(".mkif"); if(f){ const h=f.srcdoc; f.srcdoc=""; setTimeout(()=>{ f.srcdoc=h; },30); } else { MK_APP.state[rb.dataset.mkreload]="idle"; delete MK_APP.html[rb.dataset.mkreload]; render(); } }; }
window.addEventListener("message",e=>{ const d=e.data||{}; if(d.type==="hqmakerdl"&&d.blob instanceof Blob){ const f=document.querySelector(".mkif"); if(f&&e.source===f.contentWindow) dlBlob(String(d.name||"maker-file").slice(0,120),d.blob); return; } if(d.type==="hqmaker"&&d.ev==="ready"){ const key=d.app==="hype"?"hype":"nameplate"; MK_APP.state[key]="ready"; } });

/* ================= LISTING PACKS: one zip with everything needed to post an item — files, photos, title, 13 tags, description, price, attributes — plus a checklist of what's still missing ================= */
const PACK={busy:new Set()};
function packTxt(p){ const L=[]; const add=(k,v)=>{ if(v==null||v===""||(Array.isArray(v)&&!v.length)) return; L.push(k.toUpperCase()+"\n"+(Array.isArray(v)?v.join(", "):String(v))+"\n"); };
  add("title",p.title); add("price",p.price); add("tags (etsy, 13 max, 20 chars each)",p.tags); add("description",p.description); add("materials",p.materials); add("category",p.category); add("attributes",p.attributes); add("shipping & processing",p.shipping); add("photo order & alt text",p.photoNotes); add("personalization",p.personalization); add("sizes / colours",p.variants);
  add("channel",p.channel); add("brand",p.brandName); add("notes",p.note);
  return `${p.brandName||""} — LISTING PACK\nMade ${new Date().toLocaleString()} from the console (${p.kind}/${p.id})\n\n`+L.join("\n"); }
function packChecklist(p,got){ const need=[["title",!!p.title],["description",!!p.description],["13 tags",(p.tags||[]).length>=13],["price",!!p.price],["5+ photos",got.photos>=5],["print file (.3mf/.stl) or print-ready art",got.files>=1],["materials",!!p.materials],["category",!!p.category]];
  return "READY TO POST?\n"+need.map(([k,ok])=>`${ok?"[x]":"[ ]"} ${k}`).join("\n")+"\n\n"+(need.every(x=>x[1])?"Everything is here. Post it.":"Missing items are unchecked above. Ask Carla (listing text/photos) or Andy (3D files) from the console.")+"\n"; }
function packFrom(kind,id){ const B={ed:"Elevated Designs",c3d:"Charleston 3D Prints"};
  if(kind==="listing"){ const l=(S.listings||[]).find(x=>x.id===id); if(!l) return null; const d=l.draft||{}; const biz=listingBiz(l); const pi=/^printideas\//.test(String(l.design||""))?(S.printideas||[]).find(p=>p.id===String(l.design).slice(11)):null; const de=/^designs\//.test(String(l.design||""))||!pi?(S.designs||[]).find(x=>x.id===String(l.design||"").replace(/^designs\//,"")):null;
    const assets=[...(Array.isArray(l.photoIds)?l.photoIds:[]),...(pi&&pi.previewId?[pi.previewId]:[]),...(de?[de.imageId,de.printId,de.mockupId].filter(Boolean):[])].filter(x=>/^[0-9a-f]{32}$/.test(String(x)));
    const urls=[...(l.photos||[]).map(x=>typeof x==="string"?x:(x&&x.url)),...(pi?(pi.files||[]).map(f=>f.driveUrl||f.url):[]),...(l.files||[]).map(f=>f.url||f.driveUrl)].filter(Boolean);
    return {kind,id,brand:biz,brandName:B[biz],title:d.title,price:d.price,tags:d.tags,description:d.description,materials:d.materials,category:d.category,attributes:d.attributes,shipping:d.shipping,photoNotes:d.photoNotes,personalization:d.personalization,variants:d.variants||d.sizes,channel:biz==="c3d"?"Etsy (3D never goes on the Elevated Designs Shopify store)":(l.channel||"Shopify + Etsy"),note:l.note,assets:[...new Set(assets)],urls:[...new Set(urls)],files:(pi?pi.files:l.files)||[]}; }
  if(kind==="print"){ const x=(S.printideas||[]).find(p=>p.id===id); if(!x) return null; const pr=x.price||{}; return {kind,id,brand:"c3d",brandName:B.c3d,title:x.title,price:pr.sell||pr.price||x.sellPrice,tags:x.tags||x.keywords,description:x.description||x.concept,materials:x.materials||x.filament,category:x.category,attributes:x.attributes,variants:x.sizes||x.colors,channel:"Etsy (3D never goes on the Elevated Designs Shopify store)",note:x.notes,assets:[x.previewId].filter(a=>/^[0-9a-f]{32}$/.test(String(a))),urls:(x.files||[]).map(f=>f.driveUrl||f.url).filter(Boolean),files:x.files||[]}; }
  if(kind==="design"){ const d=(S.designs||[]).find(x=>x.id===id); if(!d) return null; const biz=designBiz(d); return {kind,id,brand:biz,brandName:B[biz],title:d.title,price:d.price,tags:d.tags,description:d.description||d.concept,materials:d.product?`${d.product}${d.colors?" · "+[].concat(d.colors).join(", "):""}`:"",variants:d.colors,channel:biz==="c3d"?"Etsy":"Shopify + Etsy",note:d.veraNote||d.helenNote,assets:[d.imageId,d.printId,d.mockupId].filter(a=>/^[0-9a-f]{32}$/.test(String(a))),urls:[d.imageUrl,d.printUrl,d.mockupUrl].filter(u=>u&&!/^\/_blob/.test(u)),files:[]}; }
  return null; }
async function packFetch(url){ try{ const r=await fetch(url); if(!r.ok) return null; const b=await r.blob(); return {blob:b,type:b.type}; }catch{ return null; } }
function extOf(type,name){ if(name&&/\.[a-z0-9]{2,4}$/i.test(name)) return ""; const m={"image/png":".png","image/jpeg":".jpg","image/webp":".webp","image/svg+xml":".svg","model/3mf":".3mf","application/vnd.ms-package.3dmanufacturing-3dmodel+xml":".3mf","model/stl":".stl","application/sla":".stl","application/zip":".zip","application/pdf":".pdf"}; return m[type]||""; }
async function packBuild(kind,id,quiet){ const p=packFrom(kind,id); if(!p){ toast("Nothing to pack."); return null; } const key=kind+"/"+id; if(PACK.busy.has(key)) return null; PACK.busy.add(key); if(!quiet) toast("Packing…");
  try{ const files=[]; let photos=0, models=0; const links=[]; const slug=String(p.title||id).toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,50)||id;
    let n=0; for(const a of p.assets){ const got=await packFetch("/_blob/"+a); if(!got) continue; const isImg=/^image\//.test(got.type); const is3=/3mf|stl|sla|zip/.test(got.type); const name=(isImg?`photos/photo-${String(++photos).padStart(2,"0")}`:is3?`files/model-${++models}`:`extra/file-${++n}`)+extOf(got.type); files.push({name,data:new Uint8Array(await got.blob.arrayBuffer())}); }
    for(const u of p.urls){ const got=/^\/_blob\//.test(u)||/^https?:\/\/[^/]*claude\.ai\//.test(u)?await packFetch(u):null; if(got&&got.blob.size){ const isImg=/^image\//.test(got.type); const name=(isImg?`photos/photo-${String(++photos).padStart(2,"0")}`:`files/file-${++models}`)+extOf(got.type,""); files.push({name,data:new Uint8Array(await got.blob.arrayBuffer())}); } else links.push(u); }
    (p.files||[]).forEach(f=>{ const u=f.driveUrl||f.url; if(u&&!links.includes(u)) links.push(u); });
    files.unshift({name:"listing.txt",data:packTxt(p)}); files.push({name:"listing.json",data:JSON.stringify(p,null,2)});
    if(links.length) files.push({name:"files/LINKS.txt",data:"These files live elsewhere (Google Drive / web). Open and download them:\n\n"+links.join("\n")+"\n"});
    files.push({name:"CHECKLIST.txt",data:packChecklist(p,{photos,files:models+links.length})});
    const blob=new Blob([mkZip(files)],{type:"application/zip"}); const fname=`${p.brand}-${slug}-pack.zip`;
    if(!quiet){ if(typeof dlBlob==="function") dlBlob(fname,blob); else { const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=fname; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },4000); } toast(`Pack ready: ${photos} photo${photos===1?"":"s"}, ${models} file${models===1?"":"s"}${links.length?`, ${links.length} link${links.length===1?"":"s"}`:""}.`); }
    return {blob,fname,files,photos,models,links,p}; }
  catch(e){ console.error("pack",e); toast("Couldn't build the pack."); return null; }
  finally{ PACK.busy.delete(key); } }
function packBtn(kind,id,label){ return `<button type="button" class="btn" data-pack="${esc(kind)}|${esc(id)}">${esc(label||"Export pack")}</button>`; }
async function packAll(biz){ const L=(S.listings||[]).filter(l=>listingBiz(l)===biz&&["ready","posted","drafting","new"].includes(l.status||"new")); if(!L.length){ toast("No listings to pack."); return; } toast(`Packing ${L.length} listings…`);
  const all=[]; for(const l of L){ const r=await packBuild("listing",l.id,true); if(r){ const dir=String(r.fname).replace(/-pack\.zip$/,""); for(const f of r.files) all.push({name:dir+"/"+f.name,data:f.data}); } }
  const blob=new Blob([mkZip(all)],{type:"application/zip"}); const fname=`${biz}-etsy-ready-${new Date().toISOString().slice(0,10)}.zip`; if(typeof dlBlob==="function") dlBlob(fname,blob); else { const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=fname; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },4000); } toast(`${L.length} packs in one zip, one folder each.`); }
function bindPacks(){ /* delegated once, so buttons inside pop-up cards work too */ if(PACK.bound) return; PACK.bound=true;
  document.addEventListener("click",e=>{ const b=e.target.closest("[data-pack]"); if(b){ e.preventDefault(); e.stopPropagation(); const [k,id]=b.dataset.pack.split("|"); packBuild(k,id); return; } const a=e.target.closest("[data-packall]"); if(a){ e.preventDefault(); packAll(a.dataset.packall); } },true); }
